String _buyBrowseComparisonQuantityLabel(BuyV2ComparisonQuery query) {
  final quantity = query.requestedQuantityMilli;
  final fraction = (quantity % 1000).toString().padLeft(3, '0').replaceFirst(RegExp(r'0+$'), '');
  return 'Quantity: ${quantity ~/ 1000}${fraction.isEmpty ? '' : '.$fraction'} ${query.identity.unit.name}';
}

typedef BuyV2LiveDeliveryMapBuilder =
    Widget Function(BuildContext context, BuyV2LiveDeliverySnapshot snapshot);

// Frontend form schema only; this is not a finance-data revision.
const moolBusinessFinanceFormRevision = 'business-finance-form-v1';

/// Editable native form values, never a callback request or funding decision.
@immutable
class MoolBusinessFinancePrefill {
  const MoolBusinessFinancePrefill._({
    this.purposeIds, this.contactName, this.callbackNumber, this.note,
  });

  static const allowedFields = <String>{
    'purposeIds', 'contactName', 'callbackNumber', 'note',
  };
  final List<String>? purposeIds;
  final String? contactName, callbackNumber, note;

  static String? contactNameError(String? value) =>
      value?.trim().isNotEmpty != true ? 'Enter your name'
      : value!.length > 100 ? 'Use a name of 100 characters or fewer' : null;

  static String? callbackNumberError(String? value) {
    final number = (value ?? '').replaceAll(RegExp(r'[\s()-]'), '');
    return (value?.length ?? 0) <= 24 &&
        RegExp(r'^\+?[0-9]{8,15}$').hasMatch(number)
        ? null : 'Enter a valid callback number';
  }

  static String? noteError(String? value) => (value?.length ?? 0) <= 500
      ? null : 'Use a note of 500 characters or fewer';

  factory MoolBusinessFinancePrefill.fromFields(Map<String, Object?> fields) {
    if (fields.isEmpty || fields.keys.any((key) => !allowedFields.contains(key))) {
      throw const FormatException('Review the finance details again.');
    }
    String? readText(String key) {
      if (!fields.containsKey(key)) return null;
      final value = fields[key];
      if (value is! String) {
        throw const FormatException('Review the finance details again.');
      }
      return value;
    }
    final name = readText('contactName');
    final number = readText('callbackNumber');
    final note = readText('note');
    final error = (name == null ? null : contactNameError(name)) ??
        (number == null ? null : callbackNumberError(number)) ?? noteError(note);
    if (error != null) throw FormatException(error);
    List<String>? purposes;
    if (fields.containsKey('purposeIds')) {
      final value = fields['purposeIds'];
      final allowed = {for (final need in BuyV2BusinessFinanceNeed.values) need.id};
      if (value is! List || value.isEmpty ||
          value.any((item) => item is! String || !allowed.contains(item)) ||
          value.toSet().length != value.length) {
        throw const FormatException('Choose at least one listed finance option.');
      }
      purposes = List<String>.unmodifiable(value.cast<String>());
    }
    return MoolBusinessFinancePrefill._(
      purposeIds: purposes, contactName: name,
      callbackNumber: number, note: note,
    );
  }
}

final _buyPurchaseFinanceForms = Expando<bool>('buy-purchase-finance-form');
bool buyV2PurchaseFinanceFormOpen(BuyV2Session session) => _buyPurchaseFinanceForms[session] == true;

/// Match the existing wholesale product/cart finance entry points.
bool buyV2PurchaseFinanceAvailable(BuyV2Session session) =>
    session.view == BuyV2View.product &&
        session.selectedProductId != null &&
        session.selectedProduct?.id == session.selectedProductId &&
        session.selectedProduct?.destination == BuyV2Destination.wholesale ||
    session.view == BuyV2View.cart && session.visibleCartLines.any(
        (line) => line.product.destination == BuyV2Destination.wholesale);

/// Frontend purchase-context signature, not price/eligibility/serviceability truth.
String buyV2PurchaseFinanceContextKey(BuyV2Session session) => jsonEncode([
  session.destination.name, session.view.name,
  if (session.view == BuyV2View.product)
    [session.selectedProductId, session.selectedProduct?.customerTitle, session.selectedProduct?.pack]
  else for (final line in session.cartLines)
    if (line.product.destination == BuyV2Destination.wholesale)
      [line.product.id, line.quantity, line.product.destination.name],
]);

/// Original Buy finance opener shared by manual entry and typed initial review.
Future<void> showBuyV2PurchaseFinanceSheet(BuildContext context, BuyV2Session session, {
  required Listenable scopeOwner, required bool Function() isCurrent,
  String? storeName, String? contactName, String? callbackNumber,
  MoolBusinessFinancePrefill? prefill,
}) async {
  if (!isCurrent() || !buyV2PurchaseFinanceAvailable(session) ||
      buyV2PurchaseFinanceFormOpen(session)) return;
  final source = buyV2PurchaseFinanceContextKey(session);
  final view = session.view, productId = session.selectedProductId;
  bool current() => isCurrent() && session.procurementScopeCurrent &&
      buyV2PurchaseFinanceAvailable(session) &&
      buyV2PurchaseFinanceContextKey(session) == source;
  _buyPurchaseFinanceForms[session] = true;
  try {
    await showMoolBusinessFinanceSheet(context,
      scopeOwner: scopeOwner, isCurrent: current,
      storeName: storeName, contactName: contactName, callbackNumber: callbackNumber,
      prefill: prefill,
      origin: view == BuyV2View.product ? 'product' : 'cart',
      buyingStoreId: session.procurementContext?.storeId,
      productIds: view == BuyV2View.product && productId != null ? [productId]
          : session.cartLines.where((line) => line.product.destination == BuyV2Destination.wholesale)
              .map((line) => line.product.id).toSet().toList(growable: false),
      purchaseLabel: view == BuyV2View.product && session.selectedProduct != null
          ? '${session.selectedProduct!.customerTitle} · ${session.selectedProduct!.pack}'
          : 'Wholesale / Bulk Cart',
      // Deliberately no callback receiver: prefill/review never sends a request.
    );
  } finally { _buyPurchaseFinanceForms[session] = false; }
}

/// Shared enquiry frontend. The optional receiver is deliberately unconfigured
/// until an authenticated callback service and operations queue are connected.
Future<void> showMoolBusinessFinanceSheet(
  BuildContext context, {
  required Listenable scopeOwner,
  required bool Function() isCurrent,
  String? storeName,
  String? contactName,
  String? callbackNumber,
  String? purchaseLabel,
  MoolBusinessFinancePrefill? prefill,
  String origin = 'enquiry',
  String? buyingStoreId,
  List<String> productIds = const [],
  BuyV2FinanceCallbackSubmit? onRequestCallback,
}) {
  if (!isCurrent()) return Future<void>.value();
  return showModalBottomSheet<void>(
  context: context,
  isScrollControlled: true,
  useSafeArea: true,
  showDragHandle: false,
  backgroundColor: Colors.white,
  routeSettings: const RouteSettings(name: 'business-finance'),
  builder: (context) => _BusinessFinanceSheet(
    scopeOwner: scopeOwner,
    isCurrent: isCurrent,
    storeName: storeName,
    contactName: contactName,
    callbackNumber: callbackNumber,
    purchaseLabel: purchaseLabel,
    prefill: prefill,
    origin: origin, buyingStoreId: buyingStoreId,
    productIds: List.unmodifiable(productIds), onRequestCallback: onRequestCallback,
  ),
  );
}

class _BusinessFinanceSheet extends StatefulWidget {
  const _BusinessFinanceSheet({
    required this.scopeOwner,
    required this.isCurrent,
    this.storeName,
    this.contactName,
    this.callbackNumber,
    this.purchaseLabel,
    this.prefill,
    required this.origin,
    this.buyingStoreId,
    required this.productIds,
    this.onRequestCallback,
  });
  final Listenable scopeOwner;
  final bool Function() isCurrent;
  final String? storeName, contactName, callbackNumber, purchaseLabel;
  final MoolBusinessFinancePrefill? prefill;
  final String origin;
  final String? buyingStoreId;
  final List<String> productIds;
  final BuyV2FinanceCallbackSubmit? onRequestCallback;
  @override
  State<_BusinessFinanceSheet> createState() => _BusinessFinanceSheetState();
}

class _BusinessFinanceSheetState extends State<_BusinessFinanceSheet> {
  late final TextEditingController _name;
  late final TextEditingController _number;
  final _note = TextEditingController();
  final _search = TextEditingController();
  final _formKey = GlobalKey<FormState>();
  final _purposes = <String>{'purchase'};
  bool _retired = false;
  bool _busy = false;
  BuyV2FinanceCallbackRequest? _pending;
  BuyV2FinanceCallbackReceipt? _receipt;
  String? _sendError;
  bool get _locked => _busy || _pending != null;

  Future<void> _submit() async {
    final submit = widget.onRequestCallback;
    if (_busy || _retired || !widget.isCurrent() || submit == null || _receipt != null) return;
    if (_pending == null) {
      if (_purposes.isEmpty || _formKey.currentState?.validate() != true) return;
      final random = math.Random.secure();
      try {
        _pending = BuyV2FinanceCallbackRequest(
          requestId: 'FIN-${List.generate(16, (_) => random.nextInt(256).toRadixString(16).padLeft(2, '0')).join()}',
          origin: widget.origin, buyingStoreId: widget.buyingStoreId,
          productIds: widget.productIds,
          contactName: _name.text.trim(),
          callbackNumber: _number.text.replaceAll(RegExp(r'[\s()-]'), ''),
          purposeIds: BuyV2BusinessFinanceNeed.values.where((v) => _purposes.contains(v.id)).map((v) => v.id),
          note: _note.text.trim(),
        );
      } on FormatException {
        setState(() => _sendError = 'This enquiry could not be prepared. Close this form and reopen Business finance.');
        return;
      }
    }
    FocusManager.instance.primaryFocus?.unfocus();
    setState(() { _busy = true; _sendError = null; });
    final request = _pending!;
    try {
      final receipt = await submit(request);
      if (!mounted || _retired || !widget.isCurrent()) return;
      if (!receipt.matches(request)) throw const FormatException('Unconfirmed callback receipt');
      setState(() => _receipt = receipt);
    } catch (_) {
      if (mounted && !_retired && widget.isCurrent()) {
        setState(() => _sendError = 'We could not confirm your request. Try again to check the same request.');
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Widget _confirmation(BuildContext context) {
    final receipt = _receipt!, request = _pending!;
    final local = receipt.callbackDueAt.toLocal();
    final formats = MaterialLocalizations.of(context);
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text('Callback requested', key: const Key('business-finance-confirmed'),
        style: Theme.of(context).textTheme.titleMedium),
      const SizedBox(height: 8),
      Text('Reference: ${receipt.reference}'),
      Text('Callback by ${formats.formatMediumDate(local)} · ${formats.formatTimeOfDay(TimeOfDay.fromDateTime(local))}'),
      const SizedBox(height: 8),
      Text('MoolSocial will call ${request.callbackNumber} to discuss your needs.'),
      for (final id in request.purposeIds)
        Padding(padding: const EdgeInsets.only(top: 6), child: Text(BuyV2BusinessFinanceNeed.labelFor(id))),
      const SizedBox(height: 12),
      const Text('This confirms your callback request. Funding is subject to assessment and approval.'),
    ]);
  }

  @override
  void initState() {
    super.initState();
    final prefill = widget.prefill;
    _name = TextEditingController(text: prefill?.contactName ?? widget.contactName?.trim() ?? '');
    _number = TextEditingController(text: prefill?.callbackNumber ?? widget.callbackNumber?.trim() ?? '');
    _note.text = prefill?.note ?? '';
    if (prefill?.purposeIds != null) {
      _purposes..clear()..addAll(prefill!.purposeIds!);
    }
    _scopeChanged();
    widget.scopeOwner.addListener(_scopeChanged);
  }

  void _scopeChanged() {
    // Irreversible, including account A -> B -> A before the next frame.
    if (!widget.isCurrent() && !_retired) {
      _retired = true;
      // Owner changes can arrive from the covered screen's didUpdateWidget.
      // Retire synchronously, then update this separate modal after its frame.
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() {});
      });
      WidgetsBinding.instance.ensureVisualUpdate();
    }
  }

  @override
  void dispose() {
    widget.scopeOwner.removeListener(_scopeChanged);
    _name.dispose();
    _number.dispose();
    _note.dispose();
    _search.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
      _scopeChanged();
      final theme = Theme.of(context);
      final query = _search.text.trim().toLowerCase();
      final needs = BuyV2BusinessFinanceNeed.values.where((v) =>
        v.searchText.contains(query)).toList(growable: false);
      final buyerLabel = widget.storeName?.trim().isNotEmpty == true
        ? 'For ${widget.storeName!.trim()}' : 'For your purchase';
      final view = View.of(context);
      final exportedClearance = defaultTargetPlatform == TargetPlatform.android
        ? math.max(36.0, moolAndroidExportedSemanticsClearance(
            viewPadding: EdgeInsets.fromViewPadding(view.viewPadding, view.devicePixelRatio),
            platform: defaultTargetPlatform))
        : 0.0;
      return SizedBox(
        key: const Key('business-finance-sheet'),
        height: MediaQuery.sizeOf(context).height *
          (MediaQuery.sizeOf(context).height < 650 ? 1 : .9),
        child: Padding(
          padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom),
          child: SafeArea(
            top: false,
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Padding(
                  key: const Key('business-finance-header'),
                  padding: const EdgeInsets.fromLTRB(12, 4, 8, 4),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Row(children: [
                    Expanded(child: Text('Finance',
                      style: theme.textTheme.titleMedium?.copyWith(
                        color: BuyV2Colors.navy, fontWeight: FontWeight.w700))),
                    IconButton(
                      key: const Key('business-finance-close'),
                      tooltip: 'Close Business finance',
                      onPressed: () => Navigator.of(context).pop(),
                      icon: const Icon(Icons.close_rounded),
                    ),
                  ]),
                    if (!_retired) ...[Tooltip(message: buyerLabel, child: Text(buyerLabel,
                      key: const Key('business-finance-buyer'), maxLines: 1, overflow: TextOverflow.ellipsis,
                      style: theme.textTheme.bodySmall)),
                    if (widget.purchaseLabel?.trim().isNotEmpty == true)
                      Tooltip(message: widget.purchaseLabel!, child: Text(widget.purchaseLabel!,
                        maxLines: 1, overflow: TextOverflow.ellipsis, style: theme.textTheme.bodySmall)),
                    ],
                  ]),
                ),
                const Divider(height: 1),
                Expanded(child: SingleChildScrollView(
                  key: const Key('business-finance-form-scroll'),
                  padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
                  child: _retired
                    ? const Text('Your buying account has changed. Close this form and reopen Business finance.',
                        key: Key('business-finance-owner-changed'))
                    : _receipt != null ? _confirmation(context) : Form(
                        key: _formKey,
                        autovalidateMode: AutovalidateMode.onUserInteraction,
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            if (_sendError != null) Text(_sendError!,
                              key: const Key('business-finance-submit-error'),
                              style: TextStyle(color: theme.colorScheme.error)),
                            Semantics(label: 'Search finance', hint: 'Select all that apply',
                              child: TextField(key: const Key('business-finance-search'),
                              controller: _search, enabled: !_locked,
                              style: const TextStyle(fontSize: 14),
                              decoration: const InputDecoration(hintText: 'Search finance',
                                contentPadding: EdgeInsets.symmetric(vertical: 12), isDense: true,
                                prefixIcon: Icon(Icons.search)),
                              onChanged: (_) => setState(() {}))),
                            if (needs.isEmpty) const Padding(padding: EdgeInsets.symmetric(vertical: 12),
                              child: Text('No finance options match your search.')),
                            for (var index = 0; index < needs.length; index++) ...[
                            if (index == 0 || needs[index].group != needs[index - 1].group)
                              Padding(padding: const EdgeInsets.only(top: 12, bottom: 2),
                                child: Text(needs[index].group, style: theme.textTheme.labelLarge?.copyWith(
                                  color: BuyV2Colors.navy, fontWeight: FontWeight.w700))),
                            Semantics(
                              checked: _purposes.contains(needs[index].id),
                              child: ListTile(
                                key: ValueKey('business-finance-purpose-${needs[index].label}'),
                                contentPadding: EdgeInsets.zero,
                                minLeadingWidth: 20,
                                leading: Icon(_purposes.contains(needs[index].id)
                                  ? Icons.check_box_outlined : Icons.check_box_outline_blank,
                                  color: BuyV2Colors.navy),
                                title: Text(needs[index].label),
                                subtitle: Text(needs[index].guide),
                                onTap: _locked ? null : () {
                                  if (!_retired && widget.isCurrent()) {
                                    setState(() {
                                      if (!_purposes.add(needs[index].id)) {
                                        _purposes.remove(needs[index].id);
                                      }
                                    });
                                  }
                                },
                              ),
                            )],
                            if (_purposes.isEmpty)
                              Text('Select at least one finance option.',
                                style: TextStyle(color: theme.colorScheme.error)),
                            const SizedBox(height: 12),
                            MergeSemantics(child: Semantics(label: 'Contact name', child: TextFormField(
                              key: const Key('business-finance-name'),
                              controller: _name,
                              enabled: !_locked,
                              maxLength: 100,
                              textCapitalization: TextCapitalization.words,
                              textInputAction: TextInputAction.next,
                              decoration: const InputDecoration(label: ExcludeSemantics(child: Text('Contact name')), counterText: ''),
                              validator: MoolBusinessFinancePrefill.contactNameError,
                            ))),
                            const SizedBox(height: 12),
                            MergeSemantics(child: Semantics(label: 'Callback number', child: TextFormField(
                              key: const Key('business-finance-number'),
                              controller: _number,
                              enabled: !_locked,
                              maxLength: 24,
                              keyboardType: TextInputType.phone,
                              textInputAction: TextInputAction.next,
                              decoration: const InputDecoration(label: ExcludeSemantics(child: Text('Callback number')),
                                helperText: 'Use another number if you prefer.', helperMaxLines: 2, counterText: ''),
                              validator: MoolBusinessFinancePrefill.callbackNumberError,
                            ))),
                            const SizedBox(height: 12),
                            MergeSemantics(child: Semantics(label: 'Note (optional)', child: TextFormField(
                              key: const Key('business-finance-note'),
                              controller: _note,
                              validator: MoolBusinessFinancePrefill.noteError,
                              enabled: !_locked,
                              minLines: 2,
                              maxLines: 4,
                              maxLength: 500,
                              decoration: const InputDecoration(label: ExcludeSemantics(child: Text('Note (optional)'))),
                            ))),
                            const SizedBox(height: 8),
                            const Text('MoolSocial will discuss your needs and any documents during the callback. Funding is subject to assessment and approval.'),
                          ],
                        ),
                      ),
                )),
                if (!_retired) Padding(
                  key: const Key('business-finance-footer'),
                  padding: EdgeInsets.fromLTRB(16, 8, 16,
                    12 + (MediaQuery.viewInsetsOf(context).bottom > 0 ? 0 : exportedClearance)),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
                    if (_receipt == null) Padding(padding: const EdgeInsets.only(bottom: 4),
                      child: widget.onRequestCallback == null
                        ? Tooltip(message: 'No callback request has been sent.', child: Text('Callback unavailable',
                            key: const Key('business-finance-unavailable'), textAlign: TextAlign.center,
                            style: theme.textTheme.bodySmall))
                        : Text('Within 30 min · 24/7', textAlign: TextAlign.center,
                            key: const Key('business-finance-response-time'), style: theme.textTheme.bodySmall)),
                    FilledButton(
                    key: const Key('business-finance-request'),
                    onPressed: _receipt != null ? () => Navigator.of(context).pop()
                      : widget.onRequestCallback == null || _busy || _purposes.isEmpty ? null : _submit,
                    child: Text(_receipt != null ? 'Done' : _busy ? 'Sending request…'
                      : _pending != null ? 'Check request again' : 'Request callback'),
                    ),
                  ]),
                ),
              ],
            ),
          ),
        ),
      );
  }
}

Future<void> _showBulkQuotes(BuildContext context, BuyV2Session session) async {
  final access = session.bulkQuotes;
  if (access?.active != true) return;
  try {
    var selected = false;
    await showModalBottomSheet<void>(context: context, isScrollControlled: true, useSafeArea: true, showDragHandle: true,
      builder: (sheet) => SizedBox(height: MediaQuery.sizeOf(sheet).height * .92,
        child: WorkspaceBulkQuotes(access: access!, onClose: () => Navigator.pop(sheet),
          onUseForCart: (quote) async { final saved = await session.chooseSupplierQuote(quote); selected = saved; return saved; })));
    if (selected && access!.active) session.openCart();
  } catch (_) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(const SnackBar(
        content: Text('The saved supplier agreements could not be opened. Your Cart is kept.')));
    }
  }
}

Future<void> _openOrderInvoice(
  BuildContext context, {
  required BuyV2Session session,
  required BuyV2Order order,
  BuyV2InvoiceDownloader? downloader,
  bool Function()? capturedCurrent,
  bool allowDownload = true,
}) async {
  final captured = _BuyShop04Scope.of(context);
  capturedCurrent ??= captured?.sourceCurrent;
  if (captured != null) allowDownload = allowDownload && captured.actionId == 'AI-ACT-414';
  if (capturedCurrent?.call() == false) return;
  if (order.lines.isNotEmpty) {
    if (capturedCurrent != null) {
      await showBuyV2InvoicePage(context, order: order, downloader: downloader,
        capturedCurrent: capturedCurrent, allowDownload: allowDownload);
      return;
    }
    showBuyV2InvoicePage(context, order: order, downloader: downloader);
    return;
  }
  final owner = session.customerStateStore?.ownerScope;
  final refresh = await showDialog<bool>(
    context: context,
    useRootNavigator: capturedCurrent == null,
    builder: (dialogContext) => AlertDialog(
      key: ValueKey('buy-invoice-items-unavailable-${order.id}'),
      scrollable: true,
      insetPadding: const EdgeInsets.symmetric(horizontal: 16, vertical: 24),
      title: const Text('Invoice details missing'),
      titleTextStyle: Theme.of(context).textTheme.titleMedium?.copyWith(
        fontSize: 18,
        fontWeight: FontWeight.w700,
      ),
      contentTextStyle: Theme.of(
        context,
      ).textTheme.bodyMedium?.copyWith(fontSize: 14),
      content: Text(
        'Item details for ${order.id} are missing. '
        'Refresh orders, then reopen this invoice.',
      ),
      actions: [
        TextButton(
          style: TextButton.styleFrom(
            textStyle: Theme.of(
              context,
            ).textTheme.labelLarge?.copyWith(fontSize: 14),
          ),
          onPressed: () {
            if (capturedCurrent != null && (!dialogContext.mounted ||
                !capturedCurrent() || ModalRoute.of(dialogContext)?.isCurrent != true)) return;
            Navigator.of(dialogContext).pop(false);
          },
          child: const Text('Back'),
        ),
        Align(
          widthFactor: 1,
          heightFactor: 1,
          child: FilledButton(
            key: ValueKey('buy-invoice-refresh-${order.id}'),
            style: BuyV2ActionStyle.button(
              FilledButton.styleFrom(
                textStyle: Theme.of(
                  context,
                ).textTheme.labelLarge?.copyWith(fontSize: 14),
              ),
            ),
            onPressed: capturedCurrent != null ? null : () => Navigator.of(dialogContext).pop(true),
            child: const Text('Refresh orders'),
          ),
        ),
      ],
    ),
  );
  if (refresh == true &&
      context.mounted &&
      session.procurementScopeCurrent &&
      session.customerStateStore?.ownerScope == owner) {
    await session.retryCommerce();
  }
}

String _productCountLabel(int count) =>
    '$count ${count == 1 ? 'product' : 'products'}';

String _packCountLabel(int count) => '$count ${count == 1 ? 'pack' : 'packs'}';

String _itemCountLabel(int count) => '$count ${count == 1 ? 'item' : 'items'}';

bool _containsOnlyWholesaleLines(List<BuyV2CartLine> lines) =>
    lines.isNotEmpty &&
    lines.every(
      (line) => line.product.destination == BuyV2Destination.wholesale,
    );

String _checkoutFulfilmentCountLabel(BuyV2FulfilmentGroup group) =>
    group.destination == BuyV2Destination.wholesale
    ? '${_productCountLabel(group.lines.length)} · '
          '${_packCountLabel(group.itemCount)}'
    : '${_productCountLabel(group.lines.length)} · '
          '${_itemCountLabel(group.itemCount)}';

String _checkoutDockCountLabel(BuyV2Session session) =>
    !session.checkoutRecoveryAmountKnown
    ? 'Original payment'
    : session.collectionCheckoutSelected &&
          session.checkoutLines.isEmpty &&
          session.cartLines.isNotEmpty
    ? 'Cart saved'
    : session.checkoutScope == BuyV2CartScope.wholesale ||
          _containsOnlyWholesaleLines(session.checkoutLines)
    ? '${_productCountLabel(session.checkoutLines.length)} · '
          '${_packCountLabel(session.checkoutItemCount)}'
    : _itemCountLabel(session.checkoutItemCount);

String _cartHeaderSummary(BuyV2Session session) {
  final lines = session.visibleCartLines;
  final quantity = lines.fold<int>(0, (sum, line) => sum + line.quantity);
  final quantityLabel = _containsOnlyWholesaleLines(lines)
      ? _packCountLabel(quantity)
      : _itemCountLabel(quantity);
  final context =
      session.usesMixedCartSelection && session.cartDisplayFilter != 'all'
      ? '${_cartFilterLabel(session.cartDisplayFilter)} · '
      : '';
  return '$context${_productCountLabel(lines.length)} · $quantityLabel';
}

String _cartFilterLabel(String filter) => switch (filter) {
  'shop' => 'Shop',
  'wholesale' => 'Wholesale',
  'bulk' => 'Bulk',
  _ => 'All',
};

String _cartDestinationLabel(
  BuyV2Session session,
  BuyV2Destination destination,
) {
  if (destination != BuyV2Destination.wholesale) return destination.label;
  final lines = session.cartLines.where(
    (line) => line.product.destination == destination,
  );
  final hasBulk = lines.any(
    (line) => line.product.offerClass == BuyV2OfferClass.bulk,
  );
  final hasWholesale = lines.any(
    (line) => line.product.offerClass != BuyV2OfferClass.bulk,
  );
  return hasBulk ? (hasWholesale ? 'Wholesale & Bulk' : 'Bulk') : 'Wholesale';
}

@immutable
class BuyV2GstInvoiceDetails {
  const BuyV2GstInvoiceDetails({
    required this.id,
    required this.legalName,
    required this.gstin,
    required this.billingAddress,
    this.registration = BuyV2BusinessInvoiceRegistration.registered,
  });

  final String id;
  final String legalName;
  final String gstin;
  final String billingAddress;
  final BuyV2BusinessInvoiceRegistration registration;
}

class BuyV2GstInvoiceController extends ChangeNotifier {
  BuyV2GstInvoiceController({this.store});

  final BuyV2GstInvoiceProfileStore? store;
  final Map<BuyV2Destination, bool> _requested = {
    BuyV2Destination.shop: false,
    BuyV2Destination.wholesale: false,
  };
  final Map<BuyV2Destination, BuyV2GstInvoiceDetails> _selected = {};
  final List<BuyV2GstInvoiceDetails> _savedProfiles = [];
  final Set<BuyV2Destination> _explicitPreference = {};
  int _nextId = 1;
  int _mutationRevision = 0;
  String? _ownerScope;
  bool _restoring = false;
  bool _loadFailed = false;
  bool _busy = false;
  bool _disposed = false;
  String? _message;

  bool requestedFor(BuyV2Destination destination) =>
      _requested[destination] ?? false;

  BuyV2GstInvoiceDetails? detailsFor(BuyV2Destination destination) =>
      _selected[destination];

  List<BuyV2GstInvoiceDetails> get savedProfiles =>
      List.unmodifiable(_savedProfiles);

  bool get persistenceAvailable => store?.ownerScope != null;

  bool get ownerScopeCurrent => store?.ownerScope == _ownerScope;

  bool get sessionPersistenceOnly =>
      store?.ownerScope?.startsWith('device-review-session:') ?? false;

  bool get restoring => _restoring;
  bool get loadFailed => _loadFailed;

  bool get busy => _busy;

  String? get message => _message;

  void clearMessage() {
    if (_message == null) return;
    _message = null;
    _notify();
  }

  Future<void> restore({bool force = false}) async {
    final profileStore = store;
    final ownerScope = profileStore?.ownerScope;
    if (ownerScope != _ownerScope) {
      _savedProfiles.clear();
      _selected.clear();
      _explicitPreference.clear();
      _requested.updateAll((_, value) => false);
      _mutationRevision++;
      _ownerScope = null;
    }
    if (profileStore == null || ownerScope == null) {
      _notify();
      return;
    }
    if ((!force && ownerScope == _ownerScope) || _restoring) return;
    _ownerScope = ownerScope;
    _restoring = true;
    _loadFailed = false;
    _message = null;
    final mutationRevision = _mutationRevision;
    _notify();
    try {
      final snapshot = await profileStore.read();
      if (_disposed ||
          profileStore.ownerScope != ownerScope ||
          mutationRevision != _mutationRevision) {
        return;
      }
      final restored = <BuyV2GstInvoiceDetails>[];
      final seenIds = <String>{};
      for (final record in snapshot?.profiles ?? const []) {
        final id = record.id.trim();
        final legalName = record.legalName.trim();
        final gstin = record.gstin.trim().toUpperCase();
        final billingAddress = record.billingAddress.trim();
        if (id.isEmpty ||
            legalName.isEmpty ||
            billingAddress.isEmpty ||
            (record.registration == BuyV2BusinessInvoiceRegistration.registered
                ? !_validGstin(gstin)
                : gstin.isNotEmpty) ||
            !seenIds.add(id)) {
          throw const FormatException('Invalid saved invoice recipient');
        }
        restored.add(
          BuyV2GstInvoiceDetails(
            id: id,
            legalName: legalName,
            gstin: gstin,
            billingAddress: billingAddress,
            registration: record.registration,
          ),
        );
      }
      _savedProfiles
        ..clear()
        ..addAll(restored);
      _nextId = _nextProfileNumber(restored);
      for (final destination in _selected.keys.toList()) {
        final previous = _selected[destination]!;
        if (!previous.id.startsWith('gst-profile-')) continue;
        final replacement = restored
            .where((p) => p.id == previous.id)
            .firstOrNull;
        if (replacement == null) {
          _selected.remove(destination);
          // A missing business recipient must be corrected or explicitly changed.
          _requested[destination] = true;
        } else {
          _selected[destination] = replacement;
        }
      }
      applySavedDefaults();
    } on Object {
      if (!_disposed && profileStore.ownerScope == ownerScope) {
        _loadFailed = true;
        _ownerScope = null;
        _message = 'Saved GST details could not be loaded. Try again.';
      }
    } finally {
      if (!_disposed) {
        if (profileStore.ownerScope != ownerScope) {
          _ownerScope = null;
          _savedProfiles.clear();
          _selected.clear();
        }
        _restoring = false;
        _notify();
      }
    }
  }

  int _nextProfileNumber(List<BuyV2GstInvoiceDetails> profiles) {
    var next = 1;
    for (final profile in profiles) {
      final match = RegExp(r'^gst-profile-(\d+)$').firstMatch(profile.id);
      final value = int.tryParse(match?.group(1) ?? '');
      if (value != null && value >= next) next = value + 1;
    }
    return next;
  }

  void setRequested(BuyV2Destination destination, bool requested) {
    if (destination != BuyV2Destination.shop &&
        destination != BuyV2Destination.wholesale) {
      return;
    }
    _explicitPreference.add(destination);
    if (_requested[destination] == requested) return;
    _requested[destination] = requested;
    _message = null;
    _notify();
  }

  static bool _validGstin(String value) => RegExp(
    r'^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][0-9A-Z]Z[0-9A-Z]$',
  ).hasMatch(value);

  void selectSaved(
    BuyV2Destination destination,
    BuyV2GstInvoiceDetails details,
  ) {
    _explicitPreference.add(destination);
    _requested[destination] = true;
    _selected[destination] = details;
    _message = null;
    _notify();
  }

  void applySavedDefaults() {
    if (_savedProfiles.isEmpty) return;
    for (final destination in const [
      BuyV2Destination.shop,
      BuyV2Destination.wholesale,
    ]) {
      if (_selected[destination] == null &&
          !_explicitPreference.contains(destination)) {
        if (_savedProfiles.length == 1) {
          _selected[destination] = _savedProfiles.single;
        }
        _requested[destination] = true;
      }
    }
  }

  void useForDestinations(
    BuyV2Destination from,
    Iterable<BuyV2Destination> destinations,
  ) {
    final details = _selected[from];
    if (details == null) return;
    for (final destination in destinations) {
      _explicitPreference.add(destination);
      _selected[destination] = details;
      _requested[destination] = _requested[from] ?? true;
    }
    _notify();
  }

  bool applySavedBusinessProfile() {
    const destination = BuyV2Destination.wholesale;
    if (_selected[destination] != null ||
        _savedProfiles.length != 1 ||
        _explicitPreference.contains(destination)) {
      return false;
    }
    _requested[destination] = true;
    _selected[destination] = _savedProfiles.first;
    _message = null;
    _notify();
    return true;
  }

  Future<bool> save({
    required BuyV2Destination destination,
    required String legalName,
    required String gstin,
    required String billingAddress,
    required bool remember,
    BuyV2BusinessInvoiceRegistration registration =
        BuyV2BusinessInvoiceRegistration.registered,
    bool createNew = false,
  }) async {
    if (_busy) return false;
    if (_ownerScope != null && store?.ownerScope != _ownerScope) {
      await restore(force: true);
      _message = 'Your account changed. Review GST details again.';
      _notify();
      return false;
    }
    if (remember && !persistenceAvailable) {
      _message = 'Saved GST details are unavailable. Try again.';
      _notify();
      return false;
    }
    final normalizedGstin = gstin.trim().toUpperCase();
    if (legalName.trim().length < 3 ||
        billingAddress.trim().length < 8 ||
        (registration == BuyV2BusinessInvoiceRegistration.registered
            ? !_validGstin(normalizedGstin)
            : normalizedGstin.isNotEmpty)) {
      _message = 'Check your GSTIN, legal name and billing address.';
      _notify();
      return false;
    }
    final current = createNew ? null : _selected[destination];
    final currentIsSaved =
        current != null &&
        _savedProfiles.any((profile) => profile.id == current.id);
    final shouldRemember = remember && persistenceAvailable;
    final details = BuyV2GstInvoiceDetails(
      id: shouldRemember
          ? currentIsSaved
                ? current.id
                : 'gst-profile-${_nextId++}'
          : 'gst-session-${_nextId++}',
      legalName: legalName.trim(),
      gstin: normalizedGstin,
      billingAddress: billingAddress.trim(),
      registration: registration,
    );
    if (shouldRemember) {
      final candidate = [
        details,
        ..._savedProfiles.where((item) => item.id != details.id),
      ];
      if (!await _writeProfiles(candidate)) return false;
      _savedProfiles
        ..clear()
        ..addAll(candidate);
    }
    _explicitPreference.add(destination);
    _requested[destination] = true;
    _selected[destination] = details;
    if (shouldRemember) {
      _selected.updateAll(
        (_, value) => value.id == details.id ? details : value,
      );
      applySavedDefaults();
    }
    _message = shouldRemember
        ? sessionPersistenceOnly
              ? 'GST details kept until you close the app.'
              : 'GST details saved.'
        : null;
    _notify();
    return true;
  }

  Future<bool> removeSaved(BuyV2GstInvoiceDetails details) async {
    if (_busy || !persistenceAvailable) return false;
    final candidate = _savedProfiles
        .where((profile) => profile.id != details.id)
        .toList(growable: false);
    if (candidate.length == _savedProfiles.length) return true;
    if (!await _writeProfiles(candidate)) return false;
    _savedProfiles
      ..clear()
      ..addAll(candidate);
    _selected.removeWhere((destination, selected) {
      if (selected.id != details.id) return false;
      _requested[destination] = false;
      return true;
    });
    _message = 'GST details removed.';
    _notify();
    return true;
  }

  Future<bool> _writeProfiles(List<BuyV2GstInvoiceDetails> profiles) async {
    final profileStore = store;
    final ownerScope = profileStore?.ownerScope;
    if (profileStore == null || ownerScope == null) return false;
    _busy = true;
    _message = null;
    _mutationRevision += 1;
    _notify();
    try {
      final saved = await profileStore.write(
        BuyV2GstInvoiceProfileSnapshot(
          profiles: [
            for (final profile in profiles)
              BuyV2GstInvoiceProfileRecord(
                id: profile.id,
                legalName: profile.legalName,
                gstin: profile.gstin,
                billingAddress: profile.billingAddress,
                registration: profile.registration,
              ),
          ],
        ),
      );
      if (_disposed || profileStore.ownerScope != ownerScope || !saved) {
        _message = 'GST details could not be saved. Try again.';
        return false;
      }
      _ownerScope = ownerScope;
      return true;
    } on Object {
      if (profileStore.ownerScope == ownerScope) {
        _message = 'GST details could not be saved. Try again.';
      }
      return false;
    } finally {
      if (!_disposed) {
        if (profileStore.ownerScope != ownerScope) {
          _selected.clear();
          _savedProfiles.clear();
          _explicitPreference.clear();
          _requested.updateAll((_, value) => false);
          _ownerScope = null;
          _message = 'GST details could not be saved. Try again.';
        }
        _busy = false;
        _notify();
      }
    }
  }

  void _notify() {
    if (!_disposed) notifyListeners();
  }

  @override
  void dispose() {
    _disposed = true;
    super.dispose();
  }
}

String _orderPromiseSummary(BuyV2Order order) =>
    buyV2OrderPromiseSummary(order);

String buyV2OrderArrivalSummary(
  BuyV2Session session,
  BuyV2Order order, {
  bool revised = false,
}) => buyV2OrderEstimateSummary(
  order,
  refreshState: session.orderRefreshState(order.id),
  refreshing: session.orderRefreshBusy(order.id),
  revised: revised,
);

String _orderDeliveryPartnerLabel(BuyV2Order order) {
  final name = order.deliveryPartnerName?.trim();
  if (name != null && name.isNotEmpty) return name;
  return order.status == BuyV2OrderStatus.preparing ||
          order.status == BuyV2OrderStatus.confirmed
      ? 'Not assigned yet'
      : 'Delivery partner details unavailable';
}

typedef _BuyV2PurchaseGroup = ({String? purchaseId, List<BuyV2Order> orders});

List<_BuyV2PurchaseGroup> _purchaseGroupsFor(List<BuyV2Order> orders) {
  final grouped = <String, List<BuyV2Order>>{};
  for (final order in orders) {
    final key = order.purchaseId ?? 'order:${order.id}';
    grouped.putIfAbsent(key, () => []).add(order);
  }
  return [
    for (final entry in grouped.entries)
      (
        purchaseId: entry.value.first.purchaseId,
        orders: List.unmodifiable(entry.value),
      ),
  ];
}

typedef BuyV2PartnerCatalogueHandler =
    void Function(BuyV2Product product, {bool brandOnly});

Future<void> showBuyV2SupplierPolicySheet(
  BuildContext context,
  BuyV2Session session, {
  BuyV2Product? product,
  BuyV2SupplierPolicyAddIntent? intent,
  bool Function()? capturedCurrent,
  bool useRootNavigator = true,
  ValueChanged<bool>? capturedResult,
}) async {
  final item = intent?.product ?? product;
  if (item == null || capturedCurrent?.call()==false) return;
  final policy = intent?.policy ?? session.publishedSupplierPolicyFor(item);
  if (policy == null) return;
  Future<bool>? capturedConsent;
  try {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      useRootNavigator: useRootNavigator,
      backgroundColor: Colors.white,
      builder: (sheetContext) => SafeArea(
        top: false,
        child: AnimatedBuilder(
          animation: session,
          builder: (context, _) {
            if (capturedCurrent?.call()==false || intent != null &&
                !identical(session.pendingSupplierPolicyAdd, intent)) {
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (sheetContext.mounted &&
                    (ModalRoute.of(sheetContext)?.isCurrent ?? false)) {
                  Navigator.of(sheetContext).pop();
                }
              });
              return const SizedBox.shrink();
            }
            return ConstrainedBox(
              key: const ValueKey('buy-supplier-policy-sheet'),
              constraints: BoxConstraints(
                maxHeight: MediaQuery.sizeOf(context).height * .85,
              ),
              child: SingleChildScrollView(
                padding: const EdgeInsets.all(16),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            policy.title,
                            style: context.buyBody.copyWith(
                              fontSize: 18,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                        IconButton(
                          tooltip: 'Close',
                          onPressed: () {if(capturedCurrent!=null && (!sheetContext.mounted || capturedCurrent()==false || ModalRoute.of(sheetContext)?.isCurrent!=true))return;Navigator.of(sheetContext).pop();},
                          icon: const Icon(Icons.close),
                        ),
                      ],
                    ),
                    Text(
                      buyV2CustomerStoreName(item.seller, item.storeId ?? ''),
                      style: context.buyMeta,
                    ),
                    const SizedBox(height: 12),
                    Text(policy.body, style: context.buyBody),
                    if (intent != null) ...[
                      const SizedBox(height: 16),
                      CheckboxListTile(
                        key: const ValueKey(
                          'buy-supplier-policy-accept-and-add',
                        ),
                        contentPadding: EdgeInsets.zero,
                        controlAffinity: ListTileControlAffinity.leading,
                        value: session.supplierPolicyConsentBusy,
                        title: Text(
                          intent.checkoutFingerprint != null
                              ? 'I agree to this Store’s updated policy'
                              : intent.replaceScheduledLine
                              ? 'I accept this policy and replace the delivery choice for all ${intent.initialQuantity} packs. Quantity stays unchanged.'
                              : 'I accept this policy and add ${intent.quantity} × ${item.customerTitle}',
                          style: context.buyBody,
                        ),
                        onChanged: session.supplierPolicyConsentBusy
                            ? null
                            : (checked) async {
                                if (checked != true || capturedCurrent?.call()==false) return;
                                final pending = session.acceptSupplierPolicyAndAdd(intent,isCurrent:capturedCurrent);
                                if(capturedCurrent!=null)capturedConsent=pending;
                                final added=await pending;
                                capturedResult?.call(added);
                                if (sheetContext.mounted &&
                                    (ModalRoute.of(sheetContext)?.isCurrent ??
                                        false) &&
                                    (added ||
                                        !identical(
                                          session.pendingSupplierPolicyAdd,
                                          intent,
                                        ))) {
                                  Navigator.of(sheetContext).pop();
                                }
                              },
                      ),
                      if (session.supplierPolicyConsentBusy)
                        const LinearProgressIndicator(minHeight: 2),
                      if (session.notice case final message?)
                        Text(message, style: context.buyMeta),
                    ],
                    TextButton(
                      style: TextButton.styleFrom(
                        foregroundColor: BuyV2Colors.ink,
                      ),
                      onPressed: () {if(capturedCurrent!=null && (!sheetContext.mounted || capturedCurrent()==false || ModalRoute.of(sheetContext)?.isCurrent!=true))return;Navigator.of(sheetContext).pop();},
                      child: Text(intent == null ? 'Close' : 'Cancel'),
                    ),
                  ],
                ),
              ),
            );
          },
        ),
      ),
    );
  } finally {
    if(capturedCurrent!=null && capturedConsent!=null){try{await capturedConsent;}on Object{/* Original cleanup below still runs. */}}
    if (intent != null && identical(session.pendingSupplierPolicyAdd, intent)) {
      session.cancelSupplierPolicyAdd();
    }
  }
}

String _scheduledWindowLabel(BuildContext context, BuyV2ScheduledFulfilment selected) {
  final local = MaterialLocalizations.of(context);
  final start = selected.startsAt.toLocal(), end = selected.endsAt.toLocal();
  final sameDay = DateUtils.isSameDay(start, end);
  String time(DateTime value) => local.formatTimeOfDay(TimeOfDay.fromDateTime(value),
      alwaysUse24HourFormat: MediaQuery.alwaysUse24HourFormatOf(context));
  return '${local.formatFullDate(start)} · ${time(start)} – '
      '${sameDay ? '' : '${local.formatFullDate(end)} · '}${time(end)}';
}

Future<bool> _addWithScheduledWindow(BuildContext context, BuyV2Session session,
    BuyV2Product product, BuyV2ScheduledFulfilment selected, {int? quantity,
    bool Function()? capturedCurrent, bool useRootNavigator=true}) async {
  if (session.cartChangesBlocked || capturedCurrent?.call()==false) return false;
  final original = session.cartLineFor(product.id);
  final account = session.collectionIdentity?.value;
  final replace = original != null && original.scheduledFulfilment != selected;
  if (replace) {
    final confirmed = await showDialog<bool>(
      context: context,
      useRootNavigator: useRootNavigator,
      builder: (context) => AlertDialog(
        title: const Text('Replace delivery choice?'),
        content: SingleChildScrollView(child: Text(
          '${product.customerTitle}\n'
          'Current: ${original.scheduledFulfilment == null ? 'No window selected' : _scheduledWindowLabel(context, original.scheduledFulfilment!)}\n\n'
          'New: ${_scheduledWindowLabel(context, selected)}\n\n'
          'All ${original.quantity} packs will use this window. Quantity stays unchanged. '
          'Availability and price must still be confirmed at Checkout.',
        )),
        actions: [
          TextButton(onPressed: () {if(capturedCurrent!=null && (!context.mounted || capturedCurrent()==false || ModalRoute.of(context)?.isCurrent!=true))return;Navigator.pop(context,false);}, child: const Text('Keep current')),
          TextButton(onPressed: () {if(capturedCurrent!=null && (!context.mounted || capturedCurrent()==false || ModalRoute.of(context)?.isCurrent!=true))return;Navigator.pop(context,true);}, child: const Text('Replace choice')),
        ],
      ),
    );
    if (confirmed != true || !context.mounted ||
        !identical(account, session.collectionIdentity?.value) || capturedCurrent?.call()==false) {
      return false;
    }
  }
  final saved = await session.addProductForScheduledWindow(product.id, selected,
      quantity: replace ? null : quantity, replaceLine: replace ? original : null);
  if (!context.mounted || capturedCurrent?.call()==false) return saved;
  var consentSaved=false;
  if (!saved) {
    if (session.pendingSupplierPolicyAdd case final intent?) {
      await showBuyV2SupplierPolicySheet(context, session, intent: intent,
        capturedCurrent:capturedCurrent,useRootNavigator:useRootNavigator,capturedResult:(value)=>consentSaved=value);
    } else if (session.pendingPrescriptionProductId == product.id) {
      await showBuyV2PrescriptionSheet(context, session);
    }
  }
  return saved || consentSaved;
}

class _ProductPresentationObserver extends StatefulWidget {
  const _ProductPresentationObserver({required this.session, required this.product});
  final BuyV2Session session;
  final BuyV2Product product;
  @override State<_ProductPresentationObserver> createState() => _ProductPresentationObserverState();
}
class _ProductPresentationObserverState extends State<_ProductPresentationObserver> {
  BuyV2Session? _reportedSession;
  String? _reportedProduct;
  BuyV2ProductVisitContext? _reportedVisit;
  bool _scheduled = false;
  bool _visible(BuyV2Session session, String productId, BuyV2ProductVisitContext visit) {
    if (!mounted || !identical(widget.session, session) || widget.product.id != productId || session.selectedProduct?.id != productId ||
        session.view != BuyV2View.product || !identical(session.productVisit, visit) ||
        ModalRoute.of(context)?.isCurrent != true || !TickerMode.valuesOf(context).enabled ||
        WidgetsBinding.instance.lifecycleState != null && WidgetsBinding.instance.lifecycleState != AppLifecycleState.resumed) {return false;}
    var hidden = false;
    context.visitAncestorElements((element) {if (element.widget case Offstage(offstage: true)) hidden = true; return !hidden;});
    return !hidden;
  }
  @override Widget build(BuildContext context) {
    if (!_scheduled && (!identical(_reportedSession, widget.session) || _reportedProduct != widget.product.id ||
        !identical(_reportedVisit, widget.session.productVisit))) {
      final visit = widget.session.productVisit;
      _scheduled = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        _scheduled = false;
        if (!mounted) return;
        final session = widget.session, product = widget.product, gateway = session.productPresentations;
        if (!identical(session.productVisit, visit)) {
          // The old frame lost ownership. Give the newly rendered visit its
          // own frame rather than sending the old event or dropping the new one.
          setState(() {});
          return;
        }
        if (gateway == null || !_visible(session, product.id, visit)) return;
        final id = List.generate(16, (_) => math.Random.secure().nextInt(256).toRadixString(16).padLeft(2, '0')).join();
        final original = gateway.prepare(product, id, entrySurface: visit.surface);
        if (original == null) return;
        // A rebuild is not a second presentation. Failed telemetry stays partial;
        // do not silently generate replacement commands/IDs or block commerce.
        _reportedSession = session; _reportedProduct = product.id; _reportedVisit = visit;
        if (!session.claimProductPresentation(visit, product.id)) return;
        unawaited(gateway.record(original, visible: () => _visible(session, product.id, visit)));
      });
    }
    return const SizedBox.shrink();
  }
}

/// Explicit visible-surface reads, separate from presentation telemetry. A
/// rebuild/getter is not permission to scan every catalogue product.
class _StoreStockObserver extends StatefulWidget {
  const _StoreStockObserver({required this.session, required this.products, this.cart = false});
  final BuyV2Session session;
  final List<BuyV2Product> products;
  final bool cart;
  @override State<_StoreStockObserver> createState() => _StoreStockObserverState();
}
class _StoreStockObserverState extends State<_StoreStockObserver> with WidgetsBindingObserver {
  final _attempted = <String, String>{};
  BuyV2Session? _owner;
  bool _scheduled = false;
  bool _wasVisible = false;
  int _visibilityEpoch = 0;
  @override void initState() { super.initState(); WidgetsBinding.instance.addObserver(this); }
  @override void dispose() { WidgetsBinding.instance.removeObserver(this); super.dispose(); }
  @override void didChangeAppLifecycleState(AppLifecycleState state) {
    _visibilityEpoch++; _wasVisible = false; _attempted.clear();
    if (state == AppLifecycleState.resumed && mounted) { setState(_attempted.clear); }
  }
  bool _visible(BuyV2Session session) {
    if (!mounted || !identical(widget.session, session) || ModalRoute.of(context)?.isCurrent != true ||
        !TickerMode.valuesOf(context).enabled ||
        WidgetsBinding.instance.lifecycleState != null && WidgetsBinding.instance.lifecycleState != AppLifecycleState.resumed ||
        (widget.cart ? session.view != BuyV2View.cart : session.view != BuyV2View.product)) { return false; }
    var hidden = false;
    context.visitAncestorElements((element) { if (element.widget case Offstage(offstage: true)) hidden = true; return !hidden; });
    return !hidden;
  }
  bool _includes(BuyV2Session session, BuyV2Product product, String key) => _visible(session) &&
    widget.products.any((item) => item.id == product.id) &&
    (widget.cart ? session.quantityFor(product.id) > 0 : session.selectedProduct?.id == product.id) &&
    session.storeStockRequestIdentity(product) == key;
  @override Widget build(BuildContext context) {
    final session = widget.session;
    if (!identical(_owner, session)) { _owner = session; _visibilityEpoch++; _attempted.clear(); }
    final visible = _visible(session);
    if (visible != _wasVisible) { _wasVisible = visible; _visibilityEpoch++; }
    if (!visible) { _attempted.clear(); }
    final ids = widget.products.map((p) => p.id).toSet();
    _attempted.removeWhere((id, _) => !ids.contains(id));
    if (visible && !_scheduled) {
      final pending = <({BuyV2Product product, String key})>[];
      for (final product in widget.products) {
        final key = session.storeStockRequestIdentity(product);
        if (key != null && _attempted[product.id] != key) { pending.add((product: product, key: key)); }
      }
      if (pending.isNotEmpty) {
        final epoch = _visibilityEpoch;
        _scheduled = true;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _scheduled = false;
          if (!mounted) return;
          for (final request in pending) {
            if (_visibilityEpoch != epoch || !_includes(session, request.product, request.key)) continue;
            _attempted[request.product.id] = request.key;
            unawaited(session.refreshStoreStock(request.product,
              current: () => _visibilityEpoch == epoch && _includes(session, request.product, request.key)));
          }
        });
      }
    }
    return const SizedBox.shrink();
  }
}

// Optional ownership seam for the original product details presentation only.
// Manual views have no scope and retain their original callback objects.
class _BuyCapturedProductDetails extends InheritedWidget {
  const _BuyCapturedProductDetails({required this.product,required this.current,required super.child});
  final BuyV2Product product;
  final bool Function() current;
  static _BuyCapturedProductDetails? of(BuildContext context) =>
    context.getInheritedWidgetOfExactType<_BuyCapturedProductDetails>();
  static VoidCallback? effect(BuildContext context,VoidCallback? callback) => of(context)==null?callback:null;
  static VoidCallback? read(BuildContext context,VoidCallback? callback) {
    final owner=of(context);if(owner==null||callback==null)return callback;
    return () {if(context.mounted&&owner.current())callback();};
  }
  @override bool updateShouldNotify(_BuyCapturedProductDetails oldWidget)=>current!=oldWidget.current||product!=oldWidget.product;
}

class BuyV2ProductView extends StatelessWidget {
  const BuyV2ProductView({
    super.key,
    required this.session,
    this.trailingAction,
    this.scrollController,
    this.bottomContentInset = 0,
    this.returnLabel,
    this.onReturn,
    this.onAskSeller,
    this.onOpenFinance,
    this.onVisitComparisonProduct,
    this.onOpenPartnerCatalogue,
    this.aggregateCart = false, this.capturedProduct, this.capturedCurrent,
    this.wholesaleTradeDecisionAdapter =
        const BuyV2UnavailableWholesaleTradeDecisionAdapter(),
  });

  final BuyV2Session session;
  final BuyV2Product? capturedProduct;
  final bool Function()? capturedCurrent;
  final Widget? trailingAction;
  final ScrollController? scrollController;
  final double bottomContentInset;
  final String? returnLabel;
  final VoidCallback? onReturn;
  final ValueChanged<BuyV2Product>? onAskSeller;
  final VoidCallback? onOpenFinance;
  final Future<void> Function(BuyV2Product)? onVisitComparisonProduct;
  final BuyV2PartnerCatalogueHandler? onOpenPartnerCatalogue;
  final bool aggregateCart;
  final BuyV2WholesaleTradeDecisionAdapter wholesaleTradeDecisionAdapter;

  @override
  Widget build(BuildContext context) {
    final product = capturedProduct ?? session.selectedProduct;
    if (capturedProduct != null && capturedCurrent?.call() == false) return const SizedBox.shrink();
    if (product == null) {
      return const SizedBox.shrink();
    }
    VoidCallback? captureEffect(VoidCallback? callback) => capturedProduct == null ? callback : null;
    VoidCallback captureVoid(VoidCallback callback) => capturedProduct == null ? callback : () {};
    final quantity = session.quantityFor(product.id);
    final facts = session.productFactsFor(product);
    final content = session.productContentFor(product);
    final supplierPolicy = session.publishedSupplierPolicyFor(product);
    final trust = session.marketplaceTrustFor(product);
    final productBenefits = session.productBenefitsFor(product);
    final productBenefitsState = session.productBenefitsStateFor(product);
    final variants = session.productVariantsFor(product);
    final purchaseProtection = product.purchaseProtection;
    final returnSummary =
        _nonBlankComplianceValue(purchaseProtection?.summary) ??
        _nonBlankComplianceValue(product.returnPolicy);
    final protectionRemedies =
        (purchaseProtection?.remedies ?? const <String>[])
            .map(_nonBlankComplianceValue)
            .whereType<String>()
            .toList(growable: false);
    final automaticFulfilment =
        product.destination == BuyV2Destination.shop ||
        product.destination == BuyV2Destination.wholesale;
    // Configuration identifies the selected SKU. Ingredients belong to sourced
    // details, not an unlabelled substitute for the variant in the hero.
    final identityDetail = automaticFulfilment
        ? product.customerVariant
        : _nonBlankComplianceValue(product.composition) ?? product.customerVariant;
    final sizeChart =
        automaticFulfilment &&
            content.state == BuyV2ProductContentState.ready &&
            content.sourceId.trim().isNotEmpty &&
            content.sizeChart?.appliesTo(product) == true
        ? content.sizeChart
        : null;
    final wholesale = product.destination == BuyV2Destination.wholesale;
    final storeNative = wholesale && session.procurementContext?.purpose ==
        BuyV2ProcurementPurpose.restock;
    final shop = product.destination == BuyV2Destination.shop;
    final orderability = facts.orderabilityLabel.toLowerCase();
    final buyerPromise =
        facts.storeOperatingState == BuyV2StoreOperatingState.closed
        ? facts.nextOpeningLabel?.trim().isNotEmpty == true
              ? 'Available when the store opens ${facts.nextOpeningLabel!.trim()}'
              : 'Available when the store reopens'
        : orderability.contains('unavailable') ||
              orderability.contains('out of stock')
        ? 'Currently unavailable'
        : automaticFulfilment
        ? buyV2BuyerDeliveryPromise(
            facts,
            confirmAfterStoreAcceptance:
                product.destination != BuyV2Destination.medicine &&
                BuyV2ThemeScope.refinedOf(context),
          )
        : facts.deliveryPromise;
    final offerDecision = automaticFulfilment
        ? buyV2ResolveProductOfferDecision(
            product: product,
            facts: facts,
            quantity: session.quantityFor(product.id),
          )
        : null;
    final partnerProducts = switch (product.destination) {
      BuyV2Destination.shop ||
      BuyV2Destination.wholesale => session.partnerCatalogueFor(product),
      BuyV2Destination.medicine => session.sellerContinuationsFor(product),
      BuyV2Destination.orders => const <BuyV2Product>[],
    };
    final rxBlocked =
        product.requiresPrescription &&
        !session.isPrescriptionApproved(product.id);
    final displayedWindow = session.scheduledWindowFor(product);
    final purchaseEnabled = capturedProduct == null && !session.cartChangesBlocked &&
        (!session.productScheduledReview || displayedWindow != null);
    void addProduct() {
      if (capturedProduct != null) return;
      HapticFeedback.selectionClick();
      if (session.productScheduledReview) {
        if (displayedWindow != null) {
          _addWithScheduledWindow(context, session, product, displayedWindow);
        }
        return;
      }
      final added = session.addProduct(product.id);
      if (!added && session.pendingPrescriptionProductId == product.id) {
        showBuyV2PrescriptionSheet(context, session);
      }
    }

    final storeAction = automaticFulfilment && onOpenPartnerCatalogue != null
        ? TextButton.icon(
            key: ValueKey(
              '${wholesale ? 'buy-wholesale-store-action' : 'buy-shop-seller-action'}-${product.id}',
            ),
            style: TextButton.styleFrom(
              minimumSize: const Size(48, 48),
              padding: const EdgeInsets.symmetric(horizontal: 12),
              backgroundColor: const Color(0xFFEAF2F0),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(10),
              ),
            ),
            onPressed: captureEffect(() => onOpenPartnerCatalogue!(product)),
            icon: Icon(
              Icons.storefront_outlined,
              size: 18,
              color: const Color(0xFF326C76),
            ),
            label: Text(
              wholesale ? 'Visit supplier' : 'Visit store',
              softWrap: false,
              style: const TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: BuyV2Colors.ink,
                height: 1.2,
              ),
            ),
          )
        : null;

    final storeSummary = Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _ProductStoreSummary(
          key: ValueKey('buy-product-hero-store-${product.id}'),
          product: product,
          facts: facts,
          storeNative: storeNative, capturedCurrent: capturedCurrent,
          action: automaticFulfilment ? null : storeAction,
          location: trust.state == BuyV2MarketplaceTrustState.ready
              ? trust.partnerLocation
              : null,
        ),
        if (trust.state == BuyV2MarketplaceTrustState.ready) ...[
          if (trust.partnerOrderCount case final count?)
            _DecisionRow(
              icon: Icons.inventory_2_outlined,
              label: 'Orders fulfilled',
              value: '$count',
            ),
          if (trust.serviceReliabilityLabel case final reliability?)
            _DecisionRow(
              icon: Icons.local_shipping_outlined,
              label: 'Delivery record',
              value: reliability,
            ),
        ],
      ],
    );
    final sellerActions = _ProductQuickActions(
      session: session,
      product: product,
      onAskSeller: onAskSeller,
      onVisitProduct: onVisitComparisonProduct,
      storeAction: storeAction,
    );

    final productActions = Builder(builder: (_) {
                        final actions = Row(
                        children: [
                          Expanded(
                            child: _ReturnAffordance(
                              key: ValueKey('buy-product-return-${product.id}'),
                              tightHitOwner: storeNative,
                              hitOwnerKey: storeNative ? ValueKey('buy-product-return-hit-${product.id}') : null,
                              label: capturedProduct != null ? (returnLabel ?? product.destination.label) : session.canReturnToComparedProduct
                                  ? session.productReturnLabel!
                                  : returnLabel ??
                                        session.productReturnLabel ??
                                        product.destination.label,
                              minimumHeight: storeNative ? 48 : 44,
                              onTap: capturedProduct != null
                                  ? () { if (capturedCurrent?.call() == true) onReturn?.call(); }
                                  : session.canReturnToComparedProduct ? session.closeProduct : onReturn ?? session.closeProduct,
                            ),
                          ),
                          if (automaticFulfilment) ...[
                            IconButton(
                              key: ValueKey(
                                'buy-product-action-${session.isSaved(product.id) ? 'saved' : 'save'}-${product.id}',
                              ),
                              tooltip: session.isSaved(product.id)
                                  ? 'Saved'
                                  : 'Save',
                              onPressed: captureEffect(() => session.toggleSaved(product.id)),
                              icon: Icon(
                                session.isSaved(product.id)
                                    ? Icons.bookmark_rounded
                                    : Icons.bookmark_border_rounded,
                              ),
                            ),
                            IconButton(
                              key: ValueKey(
                                'buy-product-action-share-${product.id}',
                              ),
                              tooltip: 'Share',
                              onPressed: captureEffect(() => unawaited(
                                _shareBuyV2Product(
                                  context,
                                  session: session,
                                  product: product,
                                ),
                              )),
                              icon: Icon(
                                Icons.ios_share_outlined,
                                color: const Color(0xFF326C76),
                              ),
                            ),
                          ],
                          ?trailingAction,
                        ],
                        );
                        return session.procurementContext?.purpose == BuyV2ProcurementPurpose.restock
                            ? BuyV2CartAvoidanceRegion(child: actions)
                            : actions;
    });
    final presentation = Column(
      children: [
        if (capturedProduct == null) _ProductPresentationObserver(session: session, product: product),
        if (capturedProduct == null) _StoreStockObserver(session: session, products: [product]),
        if (session.reviewDataEnabled) const BuyV2DemoCatalogueLabel(),
        if (storeNative) Padding(
          padding: const EdgeInsets.symmetric(horizontal: 10), child: productActions),
        Expanded(
          child: ListView(
            key: PageStorageKey('buy-product-${product.id}'),
            controller: scrollController,
            padding: EdgeInsets.fromLTRB(
              automaticFulfilment ? 0 : 10,
