class _PublishedStoreCouponPanel extends StatelessWidget {
  const _PublishedStoreCouponPanel({required this.session, required this.product});
  final BuyV2Session session;
  final BuyV2Product product;
  @override Widget build(BuildContext context) {
    final coupons = session.publishedStoreCouponsFor(product);
    if (coupons.isEmpty) return const SizedBox.shrink();
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      for (final coupon in coupons.take(3)) _PublishedStoreCouponTile(coupon: coupon),
      if (coupons.length > 3) TextButton(onPressed: _BuyCapturedProductDetails.read(context,() => showModalBottomSheet<void>(context: context,
        isScrollControlled: true, useSafeArea: true, builder: (context) => AnimatedBuilder(animation: session,
          builder: (context, _) {
            final current = session.publishedStoreCouponsFor(product);
            return SizedBox(height: MediaQuery.sizeOf(context).height * .8, child: Column(children: [
              ListTile(title: const Text('Store coupon terms'), trailing: IconButton(tooltip: 'Close coupon terms',
                icon: const Icon(Icons.close), onPressed: _BuyCapturedProductDetails.read(context,() => Navigator.pop(context)))),
              Expanded(child: current.isEmpty ? const Center(child: Text('These terms need checking again.'))
                : ListView.builder(padding: const EdgeInsets.all(12), itemCount: current.length,
                  itemBuilder: (context, index) => _PublishedStoreCouponTile(coupon: current[index]))),
            ]));
          }))), child: Text('View all ${coupons.length} Store coupons')),
    ]);
  }
}
class _PublishedStoreCouponTile extends StatelessWidget {
  const _PublishedStoreCouponTile({required this.coupon});
  final BuyV2PublishedStoreCoupon coupon;
  @override Widget build(BuildContext context) {
    return Padding(padding: const EdgeInsets.only(bottom: 6), child: Material(
      color: const Color(0xfff2f8f7), borderRadius: BorderRadius.circular(13),
      child: ExpansionTile(key: ValueKey('buy-published-store-coupon-${coupon.identity}'),
        tilePadding: const EdgeInsets.symmetric(horizontal: 10), childrenPadding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
        leading: const Icon(Icons.confirmation_number_outlined, color: Color(0xff256b78)),
        title: Text(coupon.name, style: context.buyBody.copyWith(fontWeight: FontWeight.w600)),
        subtitle: Text(coupon.structuredTerms == null ? 'Store-wide coupon · View terms'
          : '${coupon.structuredTerms!.scopeLabel} · View terms', style: context.buyMeta),
        children: [_publishedStoreCouponTerms(context, coupon)] )));
  }
}

Widget _publishedStoreCouponTerms(BuildContext context, BuyV2PublishedStoreCoupon coupon, {bool inCart = false}) {
  final dates = MaterialLocalizations.of(context);
  if (coupon.structuredTerms case final rich?) {
    String at(DateTime value) => '${dates.formatShortDate(value.toLocal())} ${dates.formatTimeOfDay(TimeOfDay.fromDateTime(value.toLocal()))}';
    return Align(alignment: Alignment.centerLeft, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Text(rich.savingLabel, style: context.buyBody),
      for (final line in rich.conditions) Text(line, style: context.buyMeta),
      Text('Valid ${at(coupon.validFrom)} – ${at(coupon.validUntil)}', style: context.buyMeta),
      Text('${coupon.configuredUsesPerCustomer} uses per customer · ${coupon.configuredTotalUses} campaign uses', style: context.buyMeta),
      Text('${coupon.publisherName} · Eligibility and final benefit need confirmation. No saving or extra units have been applied.', style: context.buyMeta),
    ]));
  }
  final terms = coupon.terms!;
  final saving = terms.kind == 'flat' ? '${_comparisonMoney(terms.flatAmountMinor!)} off'
    : '${(terms.percentageBasisPoints! / 100).toStringAsFixed(terms.percentageBasisPoints! % 100 == 0 ? 0 : 2)}% off';
  return Align(alignment: Alignment.centerLeft, child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
    Text(terms.kind == 'flat' ? saving : '$saving · up to ${_comparisonMoney(terms.maximumSavingMinor!)}', style: context.buyBody),
    Text('Minimum Store purchase ${_comparisonMoney(terms.minimumSpendMinor!)}', style: context.buyMeta),
    Text('Valid ${dates.formatShortDate(coupon.validFrom.toLocal())} – ${dates.formatShortDate(coupon.validUntil.toLocal())}', style: context.buyMeta),
    Text('${coupon.configuredUsesPerCustomer} ${coupon.configuredUsesPerCustomer == 1 ? 'use' : 'uses'} per customer · Campaign limit: ${coupon.configuredTotalUses} uses. This is not the remaining count.', style: context.buyMeta),
    Text(inCart ? '${coupon.publisherName} · Applies once to eligible items from this Store, not per product. Other Stores are unaffected.'
      : '${coupon.publisherName} · One saving per eligible Store basket, not per product. This information does not apply a discount; eligibility and the final saving need confirmation at Checkout.', style: context.buyMeta),
  ]));
}

class _ProductBenefitsPreview extends StatelessWidget {
  const _ProductBenefitsPreview({
    required this.session,
    required this.product,
    required this.benefits,
    required this.state,
    required this.customerMessage,
  });

  final BuyV2Session session;
  final BuyV2Product product;
  final List<BuyV2CartBenefit> benefits;
  final BuyV2CartBenefitsLoadState state;
  final String? customerMessage;

  @override
  Widget build(BuildContext context) {
    if (state == BuyV2CartBenefitsLoadState.ready && benefits.isEmpty) {
      return const SizedBox.shrink();
    }
    final visibleBenefits = benefits.take(3).toList(growable: false);
    if (state == BuyV2CartBenefitsLoadState.idle ||
        state == BuyV2CartBenefitsLoadState.loading) {
      return Container(
        key: ValueKey('buy-product-benefits-loading-${product.id}'),
        padding: const EdgeInsets.all(12),
        decoration: buyV2CardDecoration(
          context: context,
          color: BuyV2Colors.softBlue,
          radius: 15,
        ),
        child: const Row(
          children: [
            SizedBox(
              width: 18,
              height: 18,
              child: CircularProgressIndicator(strokeWidth: 2),
            ),
            SizedBox(width: 9),
            Expanded(child: Text('Checking additional benefits')),
          ],
        ),
      );
    }
    if (state == BuyV2CartBenefitsLoadState.offline ||
        state == BuyV2CartBenefitsLoadState.unavailable) {
      return Container(
        key: ValueKey('buy-product-benefits-unavailable-${product.id}'),
        padding: const EdgeInsets.all(12),
        decoration: buyV2CardDecoration(
          context: context,
          color: BuyV2Colors.softOrange,
          radius: 15,
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              'Additional benefits unavailable',
              style: context.buyBody.copyWith(fontWeight: FontWeight.w700),
            ),
            const SizedBox(height: 4),
            Text(
              customerMessage ??
                  'Additional benefits could not be checked right now.',
              style: context.buyMeta,
            ),
            const SizedBox(height: 9),
            Align(
              widthFactor: 1,
              heightFactor: 1,
              child: OutlinedButton.icon(
                style: BuyV2ActionStyle.button(),
                key: ValueKey('buy-product-benefits-retry-${product.id}'),
                onPressed: _BuyCapturedProductDetails.effect(context,() => session.refreshProductBenefits(product.id)),
                icon: const Icon(Icons.refresh_rounded),
                label: const Text('Try again'),
              ),
            ),
          ],
        ),
      );
    }

    return Container(
      key: ValueKey('buy-product-benefits-ready-${product.id}'),
      padding: const EdgeInsets.all(11),
      decoration: buyV2CardDecoration(context: context, radius: 15),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.local_offer_outlined,
                color: Color(0xFF326C76),
                size: 19,
              ),
              const SizedBox(width: 7),
              Expanded(
                child: Text(
                  'Additional checkout benefits',
                  style: context.buyTitle.copyWith(
                    fontSize: 14,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 3),
          Text(
            'Separate from the listed seller price. Eligibility is checked again at Checkout.',
            style: context.buyMeta.copyWith(fontSize: 11, height: 1.35),
          ),
          const SizedBox(height: 8),
          if (visibleBenefits.isEmpty)
            Text(
              'No additional benefits available.',
              key: ValueKey('buy-product-benefits-empty-${product.id}'),
              style: context.buyBody,
            )
          else
            for (final (index, benefit) in visibleBenefits.indexed) ...[
              _ProductBenefitPreviewTile(key: ValueKey('buy-product-benefit-owner-${BuyV2Session.benefitIdentity(benefit)}'), benefit: benefit),
              if (index != visibleBenefits.length - 1)
                const SizedBox(height: 7),
            ],
        ],
      ),
    );
  }
}

class _ProductBenefitPreviewTile extends StatelessWidget {
  const _ProductBenefitPreviewTile({super.key, required this.benefit});

  final BuyV2CartBenefit benefit;

  @override
  Widget build(BuildContext context) {
    final validUntil = benefit.validUntil;
    final paymentMethods = benefit.eligiblePaymentMethods.toList()..sort();
    final sponsor = switch (benefit.sponsor) {
      BuyV2CartBenefitSponsor.retailer => 'Retail partner',
      BuyV2CartBenefitSponsor.wholesaler => 'Wholesale partner',
      BuyV2CartBenefitSponsor.manufacturer => 'Manufacturer',
      BuyV2CartBenefitSponsor.bank => 'Bank offer',
      BuyV2CartBenefitSponsor.financialPartner => 'Payment partner',
      BuyV2CartBenefitSponsor.moolSocial => 'MoolSocial',
    };
    if (benefit.kind == BuyV2CartBenefitKind.coupon &&
        benefit.scope == BuyV2CartBenefitScope.store) {
      return Container(
        key: ValueKey('buy-product-benefit-${benefit.id}'),
        decoration: BoxDecoration(color: const Color(0xfff2f8f7),
