String _commercialPaymentTermTitle(
  BuyV2CommercialPaymentTerm term,
) => switch (term.kind) {
  BuyV2CommercialPaymentTermKind.retailAdvance ||
  BuyV2CommercialPaymentTermKind.wholesaleAdvance => 'Full advance',
  BuyV2CommercialPaymentTermKind.bookingBalanceBeforeDispatch =>
    'Booking amount · balance before dispatch',
  BuyV2CommercialPaymentTermKind.bookingBalanceOnDelivery =>
    '${term.advancePercent == null ? 'Booking amount' : '${term.advancePercent}% advance'} · balance at delivery',
  BuyV2CommercialPaymentTermKind.paymentOnDelivery => 'Payment at delivery',
  BuyV2CommercialPaymentTermKind.supplierCredit =>
    '${term.advancePercent == null || term.advancePercent == 0 ? 'Supplier credit' : '${term.advancePercent}% advance + credit'} · ${term.netDays} days',
  BuyV2CommercialPaymentTermKind.regulatedCredit =>
    '${term.financierName} credit · ${term.netDays} days',
};

String _commercialPaymentTermDetail(BuyV2CommercialPaymentTerm term) {
  final amounts = term.balanceDueMinor == 0
      ? '${_comparisonMoney(term.amountDueNowMinor)} payable now'
      : '${_comparisonMoney(term.amountDueNowMinor)} now · '
            '${_comparisonMoney(term.balanceDueMinor)} ${term.balanceDueLabel}';
  if (term.kind == BuyV2CommercialPaymentTermKind.regulatedCredit) {
    return '$amounts · APR ${term.annualPercentageRate!.toStringAsFixed(2)}% · '
        'Key facts from ${term.financierName}';
  }
  if (term.kind == BuyV2CommercialPaymentTermKind.supplierCredit) {
    return '$amounts · Published directly by ${term.supplierName}';
  }
  return amounts;
}

class _CheckoutQuoteCard extends StatelessWidget {
  const _CheckoutQuoteCard({required this.session});

  final BuyV2Session session;

  @override
  Widget build(BuildContext context) {
    final attempt = session.checkoutPaymentAttempt;
    if (session.checkoutRequiresResolution &&
        attempt == null &&
        !session.collectionCheckoutSelected) {
      final original = session.legacyCheckoutAttempt?.payment.request;
      final stacked =
          original == null || MediaQuery.textScalerOf(context).scale(14) > 18;
      return Container(
        key: const ValueKey('buy-checkout-original-payment-totals'),
        padding: const EdgeInsets.all(11),
        decoration: buyV2CardDecoration(context: context, radius: 16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _CartAmountRow(
              label: 'Original total',
              value: original == null
                  ? 'Needs checking'
                  : _comparisonMoney(original.totalMinor),
              strong: true,
              stacked: stacked,
            ),
            if (original != null)
              _CartAmountRow(
                label: 'Original amount due now',
                value: _comparisonMoney(original.amountDueNowMinor),
                stacked: stacked,
              ),
            if (original != null && original.totalMinor > original.amountDueNowMinor)
              _CartAmountRow(
                label: 'Balance due',
                value: _comparisonMoney(original.totalMinor - original.amountDueNowMinor),
                stacked: stacked,
              ),
            Text(
              'Check this payment before choosing again.',
              style: context.buyMeta,
            ),
          ],
        ),
      );
    }
    if (attempt != null) {
      final agreed = buyV2SumMinor(attempt.groups.map((group) => group.request.totalMinor));
      final placed = buyV2SumMinor(attempt.groups
          .where(
            (group) => group.state == BuyV2CheckoutSubmissionState.confirmed,
          )
          .map((group) => group.request.totalMinor));
      return Container(
        key: const ValueKey('buy-checkout-committed-totals'),
        padding: const EdgeInsets.all(11),
        decoration: buyV2CardDecoration(context: context, radius: 16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _CartAmountRow(
              label: 'Agreed total',
              value: _comparisonMoney(agreed),
              strong: true,
            ),
            if (placed > 0) ...[
              _CartAmountRow(label: 'Placed orders', value: _comparisonMoney(placed)),
              _CartAmountRow(
                label: 'Remaining orders',
                value: _comparisonMoney(agreed - placed),
              ),
            ],
          ],
        ),
      );
    }
    if (!session.checkoutQuoteRequired) return const SizedBox.shrink();
    final quote = session.checkoutQuote;
    if (session.checkoutQuoteLoadState != BuyV2CommerceLoadState.ready ||
        quote == null ||
        session.checkoutQuoteReviewRequired) {
      final loading = session.checkoutQuoteBusy;
      return Container(
        key: ValueKey(
          'buy-checkout-quote-${session.checkoutQuoteLoadState.name}',
        ),
        padding: const EdgeInsets.all(11),
        decoration: buyV2CardDecoration(context: context, radius: 15),
        child: Row(
          children: [
            SizedBox.square(
              dimension: 38,
              child: loading
                  ? const Padding(
                      padding: EdgeInsets.all(8),
                      child: CircularProgressIndicator(strokeWidth: 2),
                    )
                  : const Icon(
                      Icons.receipt_long_outlined,
                      color: BuyV2Colors.muted,
                    ),
            ),
            const SizedBox(width: 9),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    loading
                        ? 'Checking the current total'
                        : session.checkoutQuoteEnabled
                        ? 'Checkout total needs a refresh' : 'Coupon total not confirmed',
                    style: context.buyTitle.copyWith(fontSize: 13),
                  ),
                  Text(
                    loading
                        ? 'Confirming tax, freight, delivery and savings.'
                        : session.checkoutQuoteMessage ?? (session.checkoutQuoteEnabled
                              ? 'The previous total has expired. Try again.'
                              : 'Coupon savings need a confirmed Checkout total. Your Cart is unchanged.'),
                    style: context.buyMeta.copyWith(fontSize: 9),
                  ),
                ],
              ),
            ),
            if (!loading && session.checkoutQuoteEnabled)
              TextButton(
                key: const ValueKey('buy-checkout-quote-retry'),
                onPressed: _BuyShop04Scope.callback(context, _BuyShop04Intent.unrelated, session.refreshCheckoutQuote),
                child: const Text('Retry'),
              ),
          ],
        ),
      );
    }
    final itemSubtotal = buyV2SumMinor(quote.lines.map((line) => line.itemSubtotalMinor));
    final couponSaving = buyV2SumMinor(quote.lines.map((line) => line.couponSavingMinor));
    final tip = buyV2SumMinor(quote.lines.map((line) => line.tipMinor));
    return Container(
      key: const ValueKey('buy-checkout-live-quote'),
      padding: const EdgeInsets.all(11),
      decoration: buyV2CardDecoration(context: context, radius: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Expanded(
                child: Text(
                  'Current Checkout total',
                  style: context.buyTitle.copyWith(fontSize: 16),
                ),
              ),
              Text(
                'Checked now',
                style: context.buyMeta.copyWith(
                  color: BuyV2Colors.green,
                  fontSize: 8,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ],
          ),
          const SizedBox(height: 6),
          _CartAmountRow(
            label: 'Items subtotal',
            value: _comparisonMoney(itemSubtotal),
          ),
          if (couponSaving > 0)
            _CartAmountRow(
              label: 'Coupon saving',
              value: '−${_comparisonMoney(couponSaving)}',
              valueColor: BuyV2Colors.green,
            ),
          if (session.checkoutQuotedTaxMinor > 0)
            _CartAmountRow(
              label: 'GST and taxes',
              value: _comparisonMoney(session.checkoutQuotedTaxMinor),
            ),
          if (session.checkoutQuotedFreightMinor > 0)
            _CartAmountRow(
              label: 'Freight',
              value: _comparisonMoney(session.checkoutQuotedFreightMinor),
            ),
          if (session.checkoutQuotedDeliveryFeeMinor > 0)
            _CartAmountRow(
              label: 'Delivery fee',
              value: _comparisonMoney(session.checkoutQuotedDeliveryFeeMinor),
            ),
          if (tip > 0)
            _CartAmountRow(
              label: 'Optional delivery tips',
              value: _comparisonMoney(tip),
            ),
          if (session.checkoutQuotedPaymentChargeMinor > 0)
            _CartAmountRow(
              label: 'Payment charge',
              value: _comparisonMoney(session.checkoutQuotedPaymentChargeMinor),
            ),
          const Divider(height: 16),
          _CartAmountRow(
            label: 'Order total',
            value: _comparisonMoney(quote.totalMinor),
            strong: true,
          ),
          const SizedBox(height: 4),
          Text(
            'Quote ${quote.id} · valid until '
            '${MaterialLocalizations.of(context).formatTimeOfDay(TimeOfDay.fromDateTime(quote.validUntil))}',
            key: const ValueKey('buy-checkout-quote-validity'),
            style: context.buyMeta.copyWith(fontSize: 8),
          ),
        ],
      ),
    );
  }
}

class _CheckoutCommercialPaymentTerms extends StatelessWidget {
