class _WholesaleCheckoutReceivingLine extends StatelessWidget {
  const _WholesaleCheckoutReceivingLine({required this.line, required this.session,this.preparingFromCart=false});

  final BuyV2CartLine line;
  final bool preparingFromCart;
  final BuyV2Session session;

  @override
  Widget build(BuildContext context) {
    final product = line.product;
    final agreed = session.agreedUnitPriceFor(line, checkout: !preparingFromCart), subtotalMinor = session.merchandiseForLine(line, checkout: !preparingFromCart);
    final quantityLabel = _packCountLabel(line.quantity);
    final semanticLabel =
        '${product.customerTitle}. $quantityLabel. ${product.pack}. '
        'Minimum order ${_packCountLabel(product.minimumOrder)}. '
        '${_comparisonMoney(agreed ?? product.priceMinor)} per pack. ${agreed == null ? product.unitPrice : 'Agreed supplier price'}. '
        'Item total ${_comparisonMoney(subtotalMinor)}.';
    return Semantics(
      key: ValueKey('buy-wholesale-checkout-receiving-line-${product.id}'),
      container: true,
      label: semanticLabel,
      explicitChildNodes: true,
      child: LayoutBuilder(
        builder: (context, constraints) {
          final stacked =
              constraints.maxWidth < 290 ||
              MediaQuery.textScalerOf(context).scale(1) > 1.2;
          final details = Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(product.customerTitle, style: context.buyBody),
              const SizedBox(height: 2),
              Text(
                '$quantityLabel · ${product.pack}',
                style: context.buyMeta.copyWith(
                  color: BuyV2Colors.ink,
                  fontWeight: FontWeight.w600,
                ),
              ),
              const SizedBox(height: 2),
              Text(
                'Minimum order ${_packCountLabel(product.minimumOrder)} · '
                '${_comparisonMoney(agreed ?? product.priceMinor)} per pack · ${agreed == null ? product.unitPrice : 'Agreed supplier price'}',
                style: context.buyMeta,
              ),
            ],
          );
          final subtotal = Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              Column(
                crossAxisAlignment: stacked
                    ? CrossAxisAlignment.start
                    : CrossAxisAlignment.end,
                mainAxisSize: MainAxisSize.min,
                children: [
                  Text('Item total', style: context.buyMeta),
                  const SizedBox(height: 2),
                  Text(
                    _comparisonMoney(subtotalMinor),
                    style: context.buyBody.copyWith(
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ],
              ),
            ],
          );
          if (stacked) {
            return Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [details, const SizedBox(height: 6), subtotal],
            );
          }
          return Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(child: details),
              const SizedBox(width: 10),
              subtotal,
            ],
          );
        },
      ),
    );
  }
}

