String buyV2OrderRowKey({
  required int groupIndex,
  required String? purchaseId,
  required int orderIndex,
  required String orderId,
}) =>
    'buy-order-row-${purchaseId ?? 'ungrouped-$groupIndex'}-'
    '$orderIndex-$orderId';

String _buyV2PurchaseSummary(BuyV2Session session, List<BuyV2Order> orders) {
  final collections = orders.where((order) => order.collection != null).length;
  if (collections == 0) {
    final count = orders.length;
    try {
      final totalMinor = buyV2SumMinor(orders.map((order) => order.payableTotalMinor));
      return '$count ${count == 1 ? 'delivery' : 'deliveries'} · ${_comparisonMoney(totalMinor)}';
    } on FormatException {
      return '$count ${count == 1 ? 'delivery' : 'deliveries'} · Updating total';
    }
  }
  final count = orders.length;
  final kind = collections == count
      ? (count == 1 ? 'collection' : 'collections')
      : (count == 1 ? 'order' : 'orders');
  final amounts = <int>[];
  try {
    for (final order in orders) {
      if (order.collection == null) {
        amounts.add(order.payableTotalMinor);
      } else {
        final snapshot = session.collectionSnapshotFor(order.id);
        if (snapshot == null) return '$count $kind · Updating total';
        amounts.add(snapshot.totalMinor);
      }
    }
    return '$count $kind · ${_collectionMoney(buyV2SumMinor(amounts))}';
  } on FormatException {
    return '$count $kind · Updating total';
  }
}

class BuyV2OrdersView extends StatelessWidget {
  const BuyV2OrdersView({
    super.key,
    required this.session,
    required this.onOpenOrderHelp,
    this.invoiceDownloader,
    this.browseProducts,
    this.onReceivePurchasedOrder, this.readQuery, this.permittedOrder,
  });

  final BuyV2Session session;
  final ValueChanged<BuyV2Order> onOpenOrderHelp;
  final BuyV2InvoiceDownloader? invoiceDownloader;
  final Widget? browseProducts;
  final String? readQuery;
  final bool Function(BuyV2Order)? permittedOrder;
  final void Function(WorkspacePurchaseReference, WorkspacePurchaseOrder)? onReceivePurchasedOrder;

  @override
  Widget build(BuildContext context) {
    final visibleOrders=(readQuery==null?session.visibleOrderHistory:session.readOrderHistory(readQuery!))
        .where((order)=>permittedOrder?.call(order)??true).toList(growable:false);
    final sections = [
      (
        'Active',
        visibleOrders
            .where((order) => !session.orderIsCompleted(order))
            .toList(growable: false),
      ),
      (
        'Delivered',
        visibleOrders.where(session.orderIsCompleted).toList(growable: false),
      ),
    ];
    return Semantics(
      container: true,
      explicitChildNodes: true,
      label: 'Orders',
      child: ListView.custom(
        key: const PageStorageKey('buy-orders'),
        padding: const EdgeInsets.fromLTRB(8, 6, 8, 8),
        // These children are sections, each of which may contain many orders.
        // Keep their own accessible content without numbering sections as orders.
        childrenDelegate: SliverChildListDelegate([
          if (session.bulkQuotes?.active == true) ListTile(key: const ValueKey('buy-orders-bulk-quotes'),
            leading: const Icon(Icons.history_outlined), title: const Text('Past supplier agreements'),
            subtitle: const Text('Review saved agreements and unresolved requests'),
            trailing: const Icon(Icons.chevron_right_rounded), onTap: _BuyShop04Scope.callback(context, _BuyShop04Intent.unrelated, () => _showBulkQuotes(context, session))),
          if (session.purchaseReader case final reader? when reader.isCurrent && (readQuery??session.query).trim().isEmpty)
            WorkspacePurchaseOriginals(key: ValueKey(('buyer-originals',reader,session.purchaseRealm,session.procurementContext?.storeId)),
              gateway: reader, capturedCurrent: _BuyShop04Scope.of(context)?.sourceCurrent, role: WorkspaceOrderIdentityRole.buyer, realm: session.purchaseRealm,
              buyingStoreId: session.procurementContext?.storeId,
              onReceivePurchasedOrder: session.isStoreProcurement ? onReceivePurchasedOrder : null,
              onRatePurchasedItem: _BuyShop04Scope.of(context) != null || !session.privateStarsAvailable ? null : (reference, original, line) =>
                unawaited(_showPrivateStarsSheet(context, session, reference: reference, original: original, line: line))),
          if (session.canReturnToAccount) ...[
            _ReturnAffordance(
              key: const ValueKey('buy-orders-return-account'),
              label: 'Account',
              onTap: _BuyShop04Scope.callback(context, _BuyShop04Intent.unrelated, session.returnToAccount),
            ),
            const SizedBox(height: 6),
          ],
          if (session.reviewDataEnabled)
            Padding(
              padding: const EdgeInsets.fromLTRB(4, 0, 4, 6),
              child: Text(
                'Review data',
                style: context.buyMeta.copyWith(fontSize: 10),
              ),
            ),
          BuyV2FiniteIncomingTransition(
            stateKey: session.query,
            child: !session.catalogueAvailable
                ? _OrdersAvailabilityState(session: session)
                : visibleOrders.isEmpty
                ? _OrdersEmptyState(query: readQuery??session.query)
                : Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      for (final (sectionIndex, section) in sections.indexed)
                        if (section.$2.isNotEmpty)
                          Column(
                            key: ValueKey(
                              'buy-orders-section-list-${section.$1.toLowerCase()}',
                            ),
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              Padding(
                                key: ValueKey(
                                  'buy-orders-section-${section.$1.toLowerCase()}',
                                ),
                                padding: EdgeInsets.fromLTRB(
                                  4,
                                  sectionIndex == 0 ? 0 : 14,
                                  4,
                                  8,
                                ),
                                child: Semantics(
                                  container: true,
                                  header: true,
                                  child: Text(
                                    '${section.$1} · ${section.$2.length}',
                                    style: context.buyBody.copyWith(
                                      fontSize: 13,
                                      color: BuyV2Colors.muted,
                                    ),
                                  ),
                                ),
                              ),
                              for (final (groupIndex, group)
                                  in _purchaseGroupsFor(
                                    section.$2,
                                  ).indexed) ...[
                                if (group.purchaseId case final purchaseId?
                                    when group.orders.length > 1) ...[
                                  Container(
                                    key: ValueKey(
                                      'buy-purchase-group-$purchaseId',
                                    ),
                                    margin: const EdgeInsets.only(bottom: 6),
                                    padding: const EdgeInsets.symmetric(
                                      horizontal: 10,
                                      vertical: 4,
                                    ),
                                    child: BuyV2CartAvoidanceRegion(
                                      child: Row(
                                        children: [
                                          const Icon(
                                            Icons.receipt_long_outlined,
                                            color: BuyV2Colors.navy,
                                            size: 18,
                                          ),
                                          const SizedBox(width: 7),
                                          Expanded(
                                            child: Column(
                                              crossAxisAlignment:
                                                  CrossAxisAlignment.start,
                                              children: [
                                                Text(
                                                  'Purchased together',
                                                  style: context.buyBody
                                                      .copyWith(fontSize: 10.5),
                                                ),
                                                Text(
                                                  _buyV2PurchaseSummary(
                                                    session,
                                                    group.orders,
                                                  ),
                                                  style: context.buyMeta
                                                      .copyWith(fontSize: 10),
                                                ),
                                              ],
                                            ),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ),
                                ],
                                for (final (orderIndex, order)
                                    in group.orders.indexed)
                                  Padding(
                                    key: ValueKey(
                                      buyV2OrderRowKey(
                                        groupIndex:
                                            sectionIndex *
                                                (visibleOrders.length + 1) +
                                            groupIndex,
                                        purchaseId: group.purchaseId,
                                        orderIndex: orderIndex,
                                        orderId: order.id,
                                      ),
                                    ),
                                    padding: const EdgeInsets.only(bottom: 4),
                                    child: _CompactOrderCard(
                                      key: ValueKey((
                                        session.reviewDraftOwnerScope,
                                        order.id,
                                      )),
                                      session: session,
                                      order: order,
                                      invoiceDownloader: invoiceDownloader,
                                    ),
                                  ),
                              ],
                            ],
                          ),
                    ],
                  ),
          ),
          BuyV2SponsoredSlot(
            content: _BuyShop04Scope.of(context)!=null?null:session.sponsoredContentFor(
              BuyV2SponsoredPlacement.ordersAfterHistory,
            ),
          ),
          if (browseProducts case final productGrid?) ...[
            const SizedBox(height: 8),
            BuyV2CartAvoidanceRegion(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Semantics(
                    header: true,
                    child: Text(
                      'Browse more products',
                      style: context.buyTitle.copyWith(fontSize: 15),
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    'Add products now without leaving your purchase history behind.',
                    style: context.buyMeta.copyWith(fontSize: 8),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 4),
            productGrid,
          ],
          const SizedBox(height: 2),
          _OrdersContinuationRail(session: session),
        ], addSemanticIndexes: false),
      ),
    );
  }
}

class BuyV2OrderItemsView extends StatelessWidget {
  const BuyV2OrderItemsView({super.key, required this.session, this.capturedOrder});

  final BuyV2Session session;
  final BuyV2Order? capturedOrder;

  String _recordedItemSummary(BuyV2Order order, BuyV2Product product) {
    final lines = order.lines.where((line) => line.product.id == product.id);
    if (lines.isEmpty) {
      return '${product.pack} · Ordered quantity unavailable';
    }
    final quantity = lines.fold<int>(0, (total, line) => total + line.quantity);
    final amount = buyV2SumMinor(lines.map((line) => line.totalMinor));
    return '$quantity × ${product.pack} · ${_comparisonMoney(amount)}';
  }

  @override
  Widget build(BuildContext context) {
    final order = capturedOrder ?? session.selectedOrderOrNull;
    if (order == null) {
      return _MissingOrderSelection(session: session);
    }
    final recorded = order.lines.isNotEmpty;
    final products = recorded
        ? order.lines.map((line) => line.product).toList(growable: false)
        : session.productsForOrder(order);
    return ListView(
      key: ValueKey('buy-order-items-${order.id}'),
      padding: const EdgeInsets.fromLTRB(10, 7, 10, 10),
      children: [
        _ReturnAffordance(
          label: 'Order ${order.id}',
          onTap: _BuyShop04Scope.callback(context, _BuyShop04Intent.readNavigation, () => session.openTracking(order.id)),
        ),
        const SizedBox(height: 8),
        Container(
          padding: const EdgeInsets.all(11),
          decoration: buyV2CardDecoration(
            context: context,
            color: BuyV2Colors.softBlue.withValues(alpha: .65),
            border: const Color(0x26000080),
          ),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(recorded ? 'Items in this order' : 'Product links', style: context.buyTitle),
              const SizedBox(height: 3),
              Text(
                '${order.itemSummary} · ${_buyV2OrderMoney(order)}',
                style: context.buyMeta,
              ),
              const SizedBox(height: 5),
              Text(
                '${order.customerPartner} · ${order.partnerType}',
                style: context.buyBody.copyWith(fontSize: 10),
              ),
            ],
          ),
        ),
        const SizedBox(height: 8),
        if (!recorded && products.isNotEmpty) ...[
          Text(
            'Saved item details are unavailable. These links show current product information.',
            key: ValueKey('buy-order-original-items-unavailable-${order.id}'),
            style: context.buyMeta,
          ),
          const SizedBox(height: 8),
        ],
        if (products.isEmpty)
          Container(
            padding: const EdgeInsets.all(14),
            decoration: buyV2CardDecoration(context: context),
            child: Text(
              'Product details are not available for this older order.',
              style: context.buyBody,
            ),
          )
        else
          for (final product in products)
            Padding(
              padding: const EdgeInsets.only(bottom: 8),
              child: Material(
                color: Colors.transparent,
                child: InkWell(
                  key: ValueKey('buy-order-product-${product.id}'),
                  onTap: _BuyShop04Scope.callback(context, _BuyShop04Intent.unrelated, () => session.openProduct(product.id)),
                  borderRadius: BorderRadius.circular(15),
                  child: Container(
                    constraints: const BoxConstraints(minHeight: 104),
                    padding: const EdgeInsets.all(8),
                    decoration: buyV2CardDecoration(
                      context: context,
                      radius: 15,
                    ),
                    child: Row(
                      children: [
                        SizedBox(
                          width: 84,
                          height: 76,
                          child: BuyV2ProductPackshot(product: product),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              if (product.brand.trim().isNotEmpty) ...[
                                Text(
                                  product.brand,
                                  style: context.buyEyebrow.copyWith(
                                    fontSize: 8,
                                  ),
                                ),
                                const SizedBox(height: 2),
                              ],
                              Text(
                                product.customerTitle,
                                style: context.buyBody,
                              ),
                              const SizedBox(height: 3),
                              Text(
                                _recordedItemSummary(order, product),
                                style: context.buyMeta,
                              ),
                              if (order.lines.where((line) => line.product.id == product.id)
                                  .firstOrNull?.scheduledFulfilment case final selected?)
                                Text('Requested delivery · ${_scheduledWindowLabel(context, selected)}',
                                  key: ValueKey('buy-order-item-window-${product.id}'), style: context.buyMeta),
                              if (recorded)
                                if (_purchaseProtectionLines(product)
                                  case final policyLines
                                  when policyLines.isNotEmpty) ...[
                                const SizedBox(height: 3),
                                Text(
                                  'After delivery · ${policyLines.join(' · ')}',
                                  key: ValueKey(
                                    'buy-order-item-policy-${product.id}',
                                  ),
                                  style: context.buyMeta.copyWith(
                                    color: BuyV2Colors.green,
                                    fontWeight: FontWeight.w800,
                                  ),
                                ),
                              ],
                              const SizedBox(height: 4),
                              Text(
                                recorded ? 'View product details' : 'View current product details',
                                style: context.buyMeta.copyWith(
                                  color: BuyV2Colors.navy,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                            ],
                          ),
                        ),
                        const Icon(
                          Icons.chevron_right_rounded,
                          color: BuyV2Colors.navy,
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
      ],
    );
  }
}

class _OrdersAvailabilityState extends StatelessWidget {
  const _OrdersAvailabilityState({required this.session});

  final BuyV2Session session;

  @override
  Widget build(BuildContext context) {
    final loading = session.commerceLoadState == BuyV2CommerceLoadState.loading;
    return Container(
      key: ValueKey('buy-orders-${session.commerceLoadState.name}'),
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 18),
      decoration: buyV2CardDecoration(context: context, radius: 15),
      child: Column(
        children: [
          if (loading)
            const SizedBox.square(
              dimension: 28,
              child: CircularProgressIndicator(strokeWidth: 3),
            )
          else
            const Icon(
              Icons.receipt_long_outlined,
              color: BuyV2Colors.navy,
              size: 28,
            ),
          const SizedBox(height: 8),
          Text(
            loading ? 'Opening Orders' : 'Orders could not refresh',
            textAlign: TextAlign.center,
            style: context.buyTitle.copyWith(fontSize: 14),
          ),
          const SizedBox(height: 3),
          Text(
            session.commerceMessage ??
                'Try again shortly. Existing order details remain unchanged.',
            textAlign: TextAlign.center,
            style: context.buyMeta,
          ),
          if (!loading) ...[
            const SizedBox(height: 10),
            SizedBox(
              height: BuyV2Metrics.minimumTap,
              child: Align(
                widthFactor: 1,
                heightFactor: 1,
                child: FilledButton.icon(
                  style: BuyV2ActionStyle.button(),
                  key: const ValueKey('buy-orders-retry'),
                  onPressed: _BuyShop04Scope.callback(context, _BuyShop04Intent.historyRetry, () => session.retryCommerce(isCurrent:_BuyShop04Scope.of(context)?.ownerCurrent)),
                  icon: const Icon(Icons.refresh_rounded, size: 18),
                  label: const Text('Try again'),
                ),
              ),
            ),
          ],
        ],
      ),
    );
  }
}

