          const SizedBox(height: 6),
          Container(
            key: ValueKey('buy-tracking-refresh-${refreshState.name}'),
            padding: const EdgeInsets.all(10),
            decoration: buyV2CardDecoration(
              context: context,
              color: BuyV2Colors.softOrange,
