      key: ValueKey('buy-filter-semantics-${option.$1}'),
      container: true,
      button: true,
      selected: selected,
      label: '${option.$2}${selected ? ', selected' : ''}',
      hint: option.$3,
      excludeSemantics: true,
      onTap: onTap,
      child: Material(
        color: selected
            ? BuyV2ActionStyle.pressedFill
            : BuyV2ActionStyle.primaryFill,
