String _sellerTypeLabel(String source) {
  final value = source.trim().toLowerCase();
  if (value.isEmpty) return '';
  if (value.contains('manufacturer')) return 'Manufacturer';
  if (value.contains('wholesaler')) return 'Wholesaler';
  if (value.contains('distributor')) return 'Distributor';
  if (value.contains('retailer')) return 'Retailer';
  if (value.contains('shop')) return 'Dealer';
  if (value.contains('producer')) return 'Producer';
  if (value.contains('supplier')) return 'Supplier';
  return 'Seller';
}

class _ProductOwnedActionPanel extends StatelessWidget {
  const _ProductOwnedActionPanel({
    super.key,
    required this.product,
    required this.quantity,
    this.deliveryDecision,
    this.showPurchaseFacts = true,
    this.addSemanticLabel,
    this.enabled = true,
    required this.rxBlocked,
    required this.onAdd,
    required this.onEdit,
    required this.onDecrease,
    required this.onIncrease,
  });

  final BuyV2Product product;
  final int quantity;
  final String? deliveryDecision;
  final bool showPurchaseFacts;
  final String? addSemanticLabel;
  final bool rxBlocked;
  final bool enabled;
  final VoidCallback onAdd;
  final VoidCallback onEdit;
  final VoidCallback onDecrease;
  final VoidCallback onIncrease;

  @override
  Widget build(BuildContext context) {
    final commerce =
        product.destination == BuyV2Destination.shop ||
        product.destination == BuyV2Destination.wholesale;
    final action = SizedBox(
      key: ValueKey('buy-product-action-slot-${product.id}'),
      width: quantity > 0 ? _productQuantityWidth(context, quantity) : 148,
      height: 44,
      child: AnimatedSwitcher(
        duration: BuyV2Motion.resolved(context, BuyV2Motion.stateChange),
        reverseDuration: Duration.zero,
        switchInCurve: Curves.easeOutCubic,
        transitionBuilder: (child, animation) => SlideTransition(
          position: Tween<Offset>(
            begin: const Offset(.025, 0),
            end: Offset.zero,
          ).animate(animation),
          transformHitTests: false,
          textDirection: Directionality.of(context),
          child: child,
        ),
        layoutBuilder: (currentChild, _) =>
            Align(alignment: Alignment.centerRight, child: currentChild),
        child: quantity > 0
            ? _CompactProductStepper(
                key: ValueKey('buy-product-quantity-${product.id}'),
                quantity: quantity,
                minimumOrder: product.minimumOrder,
                quantityStep: product.quantityStep,
                enabled: enabled,
                onEdit: onEdit,
                onDecrease: onDecrease,
                onIncrease: onIncrease,
              )
            : commerce && !rxBlocked
            ? SizedBox(
                key: ValueKey('buy-product-add-shell-${product.id}'),
                width: 44,
                height: 44,
                child: Semantics(
                  container: true,
                  label:
                      addSemanticLabel ??
                      'Add ${product.customerTitle} to cart',
                  button: true,
                  enabled: enabled,
                  excludeSemantics: true,
                  onTap: enabled ? onAdd : null,
                  child: TextButton(
                    key: ValueKey('buy-product-primary-${product.id}'),
                    onPressed: enabled ? onAdd : null,
                    style: TextButton.styleFrom(
                      minimumSize: const Size(44, 44),
                      padding: EdgeInsets.zero,
                    ),
                    child: BuyV2AddFace(enabled: enabled),
                  ),
                ),
              )
            : SizedBox(
                key: ValueKey('buy-product-add-shell-${product.id}'),
                width: rxBlocked ? 148 : 88,
                height: 44,
                child: Semantics(
                  container: true,
                  label: rxBlocked
                      ? 'Use prescription for ${product.customerTitle}'
                      : addSemanticLabel ??
                            'Add ${product.customerTitle} to cart',
                  button: true,
                  enabled: enabled,
                  onTap: enabled ? onAdd : null,
                  excludeSemantics: true,
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      color: commerce ? BuyV2ActionStyle.primaryFill : null,
                      borderRadius: BorderRadius.circular(12),
                      border: commerce
                          ? Border.all(color: const Color(0xFFAAA3CE))
                          : null,
                    ),
                    child: Align(
                      widthFactor: 1,
                      heightFactor: 1,
                      child: FilledButton(
                        key: ValueKey('buy-product-primary-${product.id}'),
                        style: BuyV2ActionStyle.button(
                          FilledButton.styleFrom(
                            minimumSize: Size(rxBlocked ? 148 : 88, 44),
                            shape: RoundedRectangleBorder(
                              borderRadius: BorderRadius.circular(12),
                            ),
                            padding: const EdgeInsets.symmetric(horizontal: 10),
                          ),
                        ),
                        onPressed: enabled ? onAdd : null,
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          mainAxisAlignment: MainAxisAlignment.center,
                          children: [
                            Icon(
                              rxBlocked
                                  ? Icons.description_outlined
                                  : Icons.add_rounded,
                              size: 17,
                            ),
                            const SizedBox(width: 5),
                            Flexible(
                              child: Text(
                                rxBlocked ? 'Use prescription' : 'Add',
                                maxLines: 1,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(
                                  fontSize: 11,
                                  fontWeight: FontWeight.w900,
                                  height: 1,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ),
      ),
    );

    if (!showPurchaseFacts) {
      return BuyV2CartAvoidanceRegion(
        child: SizedBox(
          width: double.infinity,
          child: Wrap(
            alignment: WrapAlignment.end,
            crossAxisAlignment: WrapCrossAlignment.center,
            spacing: 8,
            runSpacing: 8,
            children: [action],
          ),
        ),
      );
    }

    final price = Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Wrap(
          crossAxisAlignment: WrapCrossAlignment.end,
          spacing: 7,
          runSpacing: 2,
          children: [
            Text(
              _comparisonMoney(product.priceMinor),
              style: const TextStyle(
                color: BuyV2Colors.navy,
                fontSize: 22,
                height: 1,
                fontWeight: FontWeight.w900,
              ),
            ),
            if (product.mrpMinor case final mrp?)
              Text(
                _comparisonMoney(mrp),
                style: const TextStyle(
                  color: BuyV2Colors.muted,
                  fontSize: 10,
                  decoration: TextDecoration.lineThrough,
                ),
              ),
          ],
        ),
        if (product.unitPrice.isNotEmpty) ...[
          const SizedBox(height: 3),
          Text(
            product.unitPrice,
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: context.buyMeta.copyWith(fontSize: 9),
          ),
        ],
        if (deliveryDecision case final delivery?) ...[
          const SizedBox(height: 3),
          Text(
            delivery,
            key: ValueKey('buy-product-action-delivery-${product.id}'),
            maxLines: 2,
            overflow: TextOverflow.ellipsis,
            style: context.buyMeta.copyWith(
              color: BuyV2Colors.green,
              fontSize: 8.5,
              fontWeight: FontWeight.w800,
            ),
          ),
        ],
      ],
    );

    return BuyV2CartAvoidanceRegion(
      child: Semantics(
        container: true,
        explicitChildNodes: true,
        child: Container(
          padding: const EdgeInsets.all(9),
          decoration: BoxDecoration(
            color: BuyV2Colors.softBlue.withValues(alpha: .42),
            borderRadius: BorderRadius.circular(15),
            border: Border.all(color: const Color(0x24000080)),
          ),
          child: LayoutBuilder(
            builder: (context, constraints) {
              final largeText = MediaQuery.textScalerOf(context).scale(1) > 1.2;
              final stack = largeText || constraints.maxWidth < 276;
              if (stack) {
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    price,
                    const SizedBox(height: 8),
                    Align(alignment: Alignment.centerRight, child: action),
                  ],
                );
              }
              return Row(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  Expanded(child: price),
                  const SizedBox(width: 8),
                  action,
                ],
              );
            },
          ),
        ),
      ),
    );
  }
}

Future<void> showBuyV2QuantityEditor(
  BuildContext context,
  BuyV2Session session,
  BuyV2Product product, {
  int? initialQuantity,
  Future<bool> Function(int)? beforeSave,
  Listenable? scopeOwner,
  bool Function()? isReviewCurrent,
  DateTime? reviewValidUntil,
  BuyV2ThemeSpec? reviewTheme,
  bool refinedCommerce = false,
  String? reviewTitle, String? reviewActionLabel, Widget? reviewDetail,
  bool reviewQuantityReadOnly=false,
  String? Function(String)? validateReviewInput,
  Future<bool> Function(int)? commitReview,
}) async {
  final bottomClearance = BuyV2AddressSheetMotion.resolveModalActionBottomInset(
    context,
  );
  await showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    showDragHandle: true,
    backgroundColor: Colors.white,
    constraints: const BoxConstraints(maxWidth: BuyV2Metrics.maxWidth),
    sheetAnimationStyle: BuyV2ProductFeedbackSheetMotion.resolve(context),
    builder: (sheetContext) {
      final editor = _QuantityEditor(
        session: session,
        product: product,
        initialQuantity: initialQuantity,
        beforeSave: beforeSave,
        scopeOwner: scopeOwner,
        isReviewCurrent: isReviewCurrent,
        reviewValidUntil: reviewValidUntil,
        reviewTitle:reviewTitle,reviewActionLabel:reviewActionLabel,reviewDetail:reviewDetail,
        reviewQuantityReadOnly:reviewQuantityReadOnly,
        validateReviewInput:validateReviewInput,commitReview:commitReview,
      );
      return Padding(
        padding: EdgeInsets.only(
          // The keyboard already covers the system navigation clearance.
          bottom: math.max(
            MediaQuery.viewInsetsOf(sheetContext).bottom,
            bottomClearance,
          ),
        ),
        child: reviewTheme == null
            ? editor
            : BuyV2ThemeScope(
                spec: reviewTheme,
                refinedCommerce: refinedCommerce,
                child: editor,
              ),
      );
    },
  );
}

class _QuantityEditor extends StatefulWidget {
  const _QuantityEditor({
    required this.session,
    required this.product,
    this.initialQuantity,
    this.beforeSave,
    this.scopeOwner,
    this.isReviewCurrent,
    this.reviewValidUntil,
    this.reviewTitle,this.reviewActionLabel,this.reviewDetail,this.validateReviewInput,this.commitReview,
    this.reviewQuantityReadOnly=false,
  });

  final BuyV2Session session;
  final BuyV2Product product;
  final int? initialQuantity;
  final Future<bool> Function(int)? beforeSave;
  final Listenable? scopeOwner;
  final bool Function()? isReviewCurrent;
  final DateTime? reviewValidUntil;
  final String? reviewTitle,reviewActionLabel;
  final Widget? reviewDetail;
  final bool reviewQuantityReadOnly;
  final String? Function(String)? validateReviewInput;
  final Future<bool> Function(int)? commitReview;

  @override
  State<_QuantityEditor> createState() => _QuantityEditorState();
}

class _QuantityEditorState extends State<_QuantityEditor> {
  late final TextEditingController _controller;
  String? _error;
  bool _closing = false;
  bool _saving = false;
  Route<dynamic>? _reviewRoute;
  Timer? _reviewExpiryTimer;

  @override
  void initState() {
    super.initState();
    _buyQuantityEditors[widget.session]=(_buyQuantityEditors[widget.session] ?? 0)+1;
    final text = '${widget.initialQuantity ?? widget.session.quantityFor(widget.product.id)}';
    _controller = TextEditingController(text: text)
      ..selection = TextSelection(baseOffset: 0, extentOffset: text.length);
    widget.scopeOwner?.addListener(_reviewOwnerChanged);
    final deadline = widget.reviewValidUntil;
    if (deadline != null) {
      final remaining = deadline.difference(DateTime.now());
      _reviewExpiryTimer = Timer(
        remaining.isNegative ? Duration.zero : remaining,
        _removeReviewRouteIfStale,
      );
    }
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _reviewRoute ??= ModalRoute.of(context);
    if (widget.isReviewCurrent?.call() == false) {
      WidgetsBinding.instance.addPostFrameCallback((_) => _removeReviewRouteIfStale());
    }
  }

  void _reviewOwnerChanged() => _removeReviewRouteIfStale();

  void _removeReviewRouteIfStale() {
    if (!mounted || _closing || widget.isReviewCurrent?.call() != false) return;
    final route = _reviewRoute;
    if (route == null || !route.isActive) return;
    _closing = true;
    Navigator.of(context).removeRoute(route);
  }

  @override
  void dispose() {
    widget.scopeOwner?.removeListener(_reviewOwnerChanged);
    _reviewExpiryTimer?.cancel();
    _buyQuantityEditors[widget.session]=(_buyQuantityEditors[widget.session] ?? 1)-1;
    _controller.dispose();
    super.dispose();
  }

  Future<void> _save() async {
    if (_closing || _saving) return;
    if (widget.isReviewCurrent?.call() == false) {
      _removeReviewRouteIfStale();
      return;
    }
    setState(() => _saving = true);
    try {
      final error = widget.validateReviewInput==null ? widget.session.cartQuantityError(
        widget.product.id,
        _controller.text,
      ):widget.validateReviewInput!(_controller.text);
      if (error != null) {
        setState(() => _error = error);
        return;
      }
      final accepted = await widget.beforeSave?.call(
        int.parse(_controller.text.trim()),
      );
      if (!mounted || _closing) return;
      if (widget.isReviewCurrent?.call() == false) {
        _removeReviewRouteIfStale();
        return;
      }
      if (accepted == false) {
        setState(
          () => _error =
              'This offer or quantity changed. Return to the comparison and refresh.',
        );
        return;
      }
      final committed=widget.commitReview==null
        ? widget.session.setCartQuantity(widget.product.id,_controller.text)
        : await widget.commitReview!(int.parse(_controller.text.trim()));
      if (!mounted || _closing) return;
      if (committed) {
        _dismiss();
      } else {
        setState(
          () => _error =
              widget.session.notice ?? (widget.commitReview==null?'Quantity could not be updated.':'Check your Cart and current status before trying again.'),
        );
      }
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  void _dismiss() {
    if (_closing || !mounted) return;
    _closing = true;
    Navigator.of(context).pop();
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag,
      padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(widget.reviewTitle ?? 'Edit quantity', style: context.buyTitle),
          const SizedBox(height: 8),
          Text(widget.product.customerTitle, style: context.buyBody),
          Text(widget.product.pack, style: context.buyMeta),
          if(widget.reviewDetail!=null)widget.reviewDetail!,
          const SizedBox(height: 16),
          TextField(
            key: const ValueKey('buy-quantity-input'),
            controller: _controller,
            readOnly:widget.reviewQuantityReadOnly,
            autofocus: true,
            keyboardType: TextInputType.number,
            textInputAction: TextInputAction.done,
            decoration: InputDecoration(
              labelText: 'Number of packs',
              helperText:
                  'Minimum ${_packCountLabel(widget.product.minimumOrder)}'
                  '${widget.product.quantityStep > 1 ? ' · Step ${widget.product.quantityStep}' : ''}',
              helperMaxLines: 3,
              errorText: _error,
              errorMaxLines: 4,
              border: const OutlineInputBorder(),
            ),
            onChanged: (_) {
              if (_error != null) setState(() => _error = null);
            },
            onSubmitted: (_) => _save(),
          ),
          const SizedBox(height: 16),
          Align(
            widthFactor: 1,
            heightFactor: 1,
            child: FilledButton(
              style: BuyV2ActionStyle.button(),
              key: const ValueKey('buy-quantity-save'),
              onPressed: _saving ? null : _save,
              child: Text(widget.reviewActionLabel ?? 'Update quantity'),
            ),
          ),
          TextButton(onPressed: _dismiss, child: const Text('Cancel')),
        ],
      ),
    );
  }
}

