class _CartBenefitsInline extends StatefulWidget {
  const _CartBenefitsInline({
    super.key,
    required this.session,
    required this.onCollapse,
    required this.destinations,
    required this.initialDestination,
  });

  final BuyV2Session session;
  final VoidCallback onCollapse;
  final List<BuyV2Destination> destinations;
  final BuyV2Destination initialDestination;

  @override
  State<_CartBenefitsInline> createState() => _CartBenefitsInlineState();
}

class _CartBenefitsInlineState extends State<_CartBenefitsInline> {
  late BuyV2Destination _destination = widget.initialDestination;
  late String _filter = widget.session.cartDisplayFilter;
  BuyV2CartBenefitKind _kind = BuyV2CartBenefitKind.coupon;
  bool _refreshingStoreCoupons = false;
  String? _storeCouponRefreshMessage;
  int _storeCouponRefreshSequence = 0;

  Future<void> _refreshStoreCoupons(BuyV2Session owner) async {
    if (!mounted || !identical(widget.session, owner)) return;
    final products = owner.cartStoreCouponRefreshProducts;
    if (_refreshingStoreCoupons || owner.cartChangesBlocked || products.isEmpty) return;
    final sequence = ++_storeCouponRefreshSequence;
    setState(() { _refreshingStoreCoupons = true; _storeCouponRefreshMessage = null; });
    final results = await Future.wait(products.map((product) => owner.refreshPublishedStoreCoupons(product.id)));
    if (!mounted || !identical(widget.session, owner) || sequence != _storeCouponRefreshSequence) return;
    setState(() {
      _refreshingStoreCoupons = false;
      _storeCouponRefreshMessage = results.every((success) => success)
        ? 'Store coupons refreshed.'
        : 'Some Store coupons could not be refreshed. Your Cart and selections are kept.';
    });
  }

  @override
  void initState() {
    super.initState();
    _followCartFilter();
    widget.session.addListener(_sessionChanged);
    _scheduleBenefitsRead(widget.session);
  }

  void _scheduleBenefitsRead(BuyV2Session ownerSession) {
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !identical(widget.session, ownerSession)) return;
      final seen = <String>{};
      for (final line in ownerSession.cartLines) {
        final listing = line.product.publicListingIdentity;
        if (listing != null && seen.add('${listing.realm}:${listing.storeId}')) {
          unawaited(ownerSession.refreshPublishedStoreCoupons(line.product.id));
        }
      }
    });
    if (ownerSession.liveCartBenefitsEnabled &&
        ownerSession.cartBenefitsLoadState !=
            BuyV2CartBenefitsLoadState.ready) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted && identical(widget.session, ownerSession)) unawaited(ownerSession.refreshCartBenefits());
      });
    }
  }

  void _followCartFilter() {
    final destination = switch (_filter) {
      'shop' => BuyV2Destination.shop,
      'wholesale' || 'bulk' => BuyV2Destination.wholesale,
      _ => _destination,
    };
    if (widget.destinations.contains(destination)) _destination = destination;
  }

  void _sessionChanged() {
    if (mounted) setState(() {});
  }

  @override
  void didUpdateWidget(covariant _CartBenefitsInline oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(oldWidget.session, widget.session)) {
      _storeCouponRefreshSequence++;
      _refreshingStoreCoupons = false;
      _storeCouponRefreshMessage = null;
      oldWidget.session.removeListener(_sessionChanged);
      widget.session.addListener(_sessionChanged);
      _scheduleBenefitsRead(widget.session);
    }
    if (_filter != widget.session.cartDisplayFilter) {
      _filter = widget.session.cartDisplayFilter;
      _followCartFilter();
    }
    if (!widget.destinations.contains(_destination)) {
      _destination = widget.initialDestination;
    }
  }

  @override
  void dispose() {
    widget.session.removeListener(_sessionChanged);
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final ownerSession = widget.session;
    final combined =
        !widget.session.isStoreProcurement &&
        !widget.destinations.contains(BuyV2Destination.medicine);
    final destinations = combined
        ? widget.destinations
              .where(
                (destination) => switch (_filter) {
                  'shop' => destination == BuyV2Destination.shop,
                  'wholesale' ||
                  'bulk' => destination == BuyV2Destination.wholesale,
                  _ => true,
                },
              )
              .toList()
        : [_destination];
    final coupons = [
      for (final destination in destinations)
        ...widget.session.cartBenefits(
          kind: BuyV2CartBenefitKind.coupon,
          destination: destination,
        ),
    ];
    final paymentOffers = [
      for (final destination in destinations)
        ...widget.session.cartBenefits(
          kind: BuyV2CartBenefitKind.paymentOffer,
          destination: destination,
        ),
    ];
    final benefits = _kind == BuyV2CartBenefitKind.coupon
        ? coupons
        : paymentOffers;
    final opportunities = [
      if (_kind == BuyV2CartBenefitKind.coupon)
        for (final destination in destinations)
          ?widget.session.cartOfferOpportunity(destination: destination),
    ];
    Widget cardFor(BuyV2CartBenefit benefit) => _CartBenefitCard(
      key: ValueKey('buy-cart-benefit-owner-${BuyV2Session.benefitIdentity(benefit)}'),
      benefit: benefit,
      enabled: !widget.session.cartChangesBlocked,
      scopeLabel: benefit.scope == BuyV2CartBenefitScope.platform
          ? null
          : widget.session.cartLines
                .where((line) => benefit.appliesTo(line.product))
                .map((line) => line.product.customerTitle)
                .toSet()
                .join(' · '),
      colourIndex: benefits.indexOf(benefit),
      paymentStatus: benefit.kind == BuyV2CartBenefitKind.paymentOffer
          ? _paymentOfferStatus(widget.session, benefit)
          : null,
      selected: widget.session.isCartBenefitSelected(benefit),
      onSelect: () {
        if (!mounted || !identical(widget.session, ownerSession)) return;
        HapticFeedback.selectionClick();
        ownerSession.chooseCartBenefit(benefit);
      },
      onRemove: () {
        if (!mounted || !identical(widget.session, ownerSession)) return;
        HapticFeedback.selectionClick();
        ownerSession.removeCartBenefit(
          kind: benefit.kind,
          destination: benefit.destination,
          expectedBenefit: benefit,
        );
      },
    );
    return Column(
      key: const ValueKey('buy-cart-benefits-inline'),
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        if (!combined && widget.destinations.length > 1)
          _CartBenefitDestinationSelector(
            session: widget.session,
            destinations: widget.destinations,
            selected: _destination,
            onChanged: (value) {
              HapticFeedback.selectionClick();
              setState(() => _destination = value);
            },
          ),
        Row(
          children: [
            Expanded(
              child: _CartBenefitKindSelector(
                kind: _kind,
                couponCount: coupons.length + ownerSession.cartStoreCoupons.length,
                paymentOfferCount: paymentOffers.length,
                onChanged: (value) {
                  HapticFeedback.selectionClick();
                  setState(() => _kind = value);
                },
              ),
            ),
            IconButton(
              key: const ValueKey('buy-cart-coupons'),
              tooltip: 'Collapse coupons and offers',
              onPressed: widget.onCollapse,
              icon: const Icon(Icons.expand_less_rounded, size: 20),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 44, minHeight: 44),
            ),
          ],
        ),
        const SizedBox(height: 6),
        if (_kind == BuyV2CartBenefitKind.coupon && ownerSession.cartStoreCouponRefreshProducts.isNotEmpty) ...[
          Align(alignment: Alignment.centerRight, child: TextButton.icon(
            key: const ValueKey('buy-cart-refresh-store-coupons'),
            onPressed: _refreshingStoreCoupons || ownerSession.cartChangesBlocked ? null : () => _refreshStoreCoupons(ownerSession),
            icon: const Icon(Icons.refresh_rounded, size: 18),
            label: Text(_refreshingStoreCoupons ? 'Refreshing Store coupons…' : 'Refresh Store coupons'))),
          if (_storeCouponRefreshMessage case final message?) Text(message, style: context.buyMeta),
        ],
        if (_kind == BuyV2CartBenefitKind.coupon && ownerSession.cartStoreCoupons.isNotEmpty) ...[
          for (final coupon in ownerSession.cartStoreCoupons.take(2))
            _CartStoreCouponRow(session: ownerSession, coupon: coupon),
          if (ownerSession.cartStoreCoupons.length > 2)
            TextButton(onPressed: () => showModalBottomSheet<void>(context: context, isScrollControlled: true,
              builder: (context) => SafeArea(child: SizedBox(height: MediaQuery.sizeOf(context).height * .7,
                child: AnimatedBuilder(animation: ownerSession, builder: (context, _) => ListView(
                  padding: const EdgeInsets.all(16), children: [
                    Text('Store coupons', style: context.buyBody),
                    for (final coupon in ownerSession.cartStoreCoupons) _CartStoreCouponRow(session: ownerSession, coupon: coupon),
                  ]))))), child: Text('View all ${ownerSession.cartStoreCoupons.length} Store coupons')),
        ],
        if (_kind == BuyV2CartBenefitKind.coupon && ownerSession.isStoreProcurement)
          Text('Store offers are not connected for this business purchase yet.', style: context.buyMeta)
        else if (widget.session.cartBenefitsLoadState != BuyV2CartBenefitsLoadState.ready &&
            (_kind != BuyV2CartBenefitKind.coupon || ownerSession.cartStoreCoupons.isEmpty || ownerSession.checkoutBenefitReviewRequired))
          _CartBenefitEligibilityState(session: widget.session)
        else if (benefits.isEmpty && (_kind != BuyV2CartBenefitKind.coupon || ownerSession.cartStoreCoupons.isEmpty))
          if (destinations.length > 1)
            Padding(
              padding: const EdgeInsets.symmetric(vertical: 12),
              child: Text(
                _kind == BuyV2CartBenefitKind.coupon
                    ? 'No coupons for these products right now'
                    : 'No payment offers for these products right now',
                style: context.buyMeta,
              ),
            )
          else
            _CartBenefitEmptyState(destination: _destination, kind: _kind)
        else if (benefits.length == 1)
          cardFor(benefits.single)
        else
          LayoutBuilder(
            builder: (context, constraints) => SingleChildScrollView(
              key: PageStorageKey(
                'buy-cart-benefits-carousel-${_destination.name}-${_kind.name}',
              ),
              scrollDirection: Axis.horizontal,
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  for (var index = 0; index < benefits.length; index++)
                    Padding(
                      padding: EdgeInsets.only(
                        right: index == benefits.length - 1 ? 0 : 8,
                      ),
                      child: SizedBox(
                        width: constraints.maxWidth - 18,
                        child: Semantics(
                          container: true,
                          label: 'Offer ${index + 1} of ${benefits.length}',
                          child: cardFor(benefits[index]),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        for (final value in opportunities)
          ExpansionTile(
            key: opportunities.length == 1
                ? const ValueKey('buy-cart-offer-opportunity')
                : ValueKey(
                    'buy-cart-offer-opportunity-${value.benefit.destination.name}',
                  ),
            dense: true,
            tilePadding: EdgeInsets.zero,
            childrenPadding: const EdgeInsets.only(bottom: 6),
            shape: const Border(),
            collapsedShape: const Border(),
            title: Text(
              'Add ${_comparisonMoney(value.remainingSpendMinor)} more to qualify',
              style: context.buyBody.copyWith(fontSize: 12),
            ),
            subtitle: Text(
              '${value.benefit.title} · '
              '${value.benefit.scope == BuyV2CartBenefitScope.platform ? '${value.benefit.destination.label} products' : widget.session.cartLines.where((line) => value.benefit.appliesTo(line.product)).map((line) => value.benefit.scope == BuyV2CartBenefitScope.store ? line.product.seller : '${line.product.customerTitle} · ${line.product.seller}').toSet().join(' · ')}',
              style: context.buyMeta.copyWith(fontSize: 11),
            ),
            children: [
              Align(
                alignment: Alignment.centerLeft,
                child: Text(
                  '${value.benefit.detail}\n'
                  'Save ${_comparisonMoney(value.benefit.savingAmountMinor)} on eligible products. '
                  'Minimum ${_comparisonMoney(value.benefit.minimumSpendMinor!)}. '
                  'Select the coupon when eligible; it is not applied automatically.',
                  style: context.buyMeta.copyWith(fontSize: 11),
                ),
              ),
            ],
          ),
      ],
    );
  }
}

class _CartStoreCouponRow extends StatelessWidget {
  const _CartStoreCouponRow({required this.session, required this.coupon,
    this.capturedCurrent,this.reviewApply,this.reviewRemove});
  final BuyV2Session session;
  final BuyV2PublishedStoreCoupon coupon;
  final bool Function()? capturedCurrent;
  final VoidCallback? reviewApply,reviewRemove;
  @override Widget build(BuildContext context) {
    final selected = session.selectedStoreCouponFor(coupon), busy = session.storeCouponChecking(coupon);
    final review = session.storeCouponNeedsReview(coupon), confirmed = session.storeCouponQuoteConfirmed(coupon);
    final terms = coupon.terms;
    final saving = coupon.structuredTerms?.savingLabel ?? (terms!.kind == 'flat' ? '${_comparisonMoney(terms.flatAmountMinor!)} off'
      : '${(terms.percentageBasisPoints! / 100).toStringAsFixed(terms.percentageBasisPoints! % 100 == 0 ? 0 : 2)}% off');
    return Padding(key: ValueKey('buy-cart-store-coupon-${coupon.identity}'),
      padding: const EdgeInsets.symmetric(vertical: 6), child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Padding(padding: EdgeInsets.only(top: 2, right: 8),
            child: Icon(Icons.confirmation_number_outlined, size: 19, color: Color(0xff256b78))),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(coupon.name, style: context.buyBody.copyWith(fontWeight: FontWeight.w600)),
            Text('${coupon.publisherName} · ${coupon.structuredTerms?.scopeLabel ?? 'Store-wide'} · $saving', style: context.buyMeta),
          ])),
        ]),
        if (selected != null) Text(review ? 'Cart changed or check expired. Recheck before using this coupon.'
          : confirmed ? 'Saving ${_comparisonMoney(selected.savingMinor!)} confirmed in the total.'
          : 'Eligible saving ${_comparisonMoney(selected.savingMinor!)} · not yet included in the total.', style: context.buyMeta),
        if (session.storeCouponMessage(coupon) case final message?) Text(message, style: context.buyMeta),
        Material(color: Colors.transparent, child: ExpansionTile(key: ValueKey('buy-cart-store-coupon-terms-${coupon.identity}'),
          tilePadding: EdgeInsets.zero, childrenPadding: const EdgeInsets.only(bottom: 6),
          title: Text(session.storeCouponAdvertisementCurrent(coupon) ? 'View terms' : 'Previously checked terms', style: context.buyMeta),
          children: [_publishedStoreCouponTerms(context, coupon, inCart: true)])),
        if (coupon.structuredTerms != null)
          Text('Applying this offer is not connected yet.', style: context.buyMeta),
        Wrap(spacing: 8, alignment: WrapAlignment.end, children: [
          if (selected != null) TextButton(onPressed: session.cartChangesBlocked || busy || capturedCurrent?.call()==false || capturedCurrent!=null && reviewRemove==null
            ? null : () {if(capturedCurrent?.call()==false)return;if(reviewRemove!=null){reviewRemove!();}else{session.removeStoreCoupon(coupon,expectedSelection:selected);}},
            child: const Text('Remove')),
          TextButton(onPressed: session.cartChangesBlocked || busy || coupon.structuredTerms != null || capturedCurrent?.call()==false || capturedCurrent!=null && reviewApply==null
            ? null : () {if(capturedCurrent?.call()==false)return;if(reviewApply!=null){reviewApply!();}else{unawaited(session.chooseStoreCoupon(coupon));}},
            child: Text(busy ? 'Checking…' : selected == null ? 'Apply' : review ? 'Recheck' : 'Check again')),
        ]),
      ]));
  }
}

class _CartBenefitDestinationSelector extends StatelessWidget {
  const _CartBenefitDestinationSelector({
    required this.session,
    required this.destinations,
    required this.selected,
    required this.onChanged,
  });

  final BuyV2Session session;
  final List<BuyV2Destination> destinations;
  final BuyV2Destination selected;
  final ValueChanged<BuyV2Destination> onChanged;

  @override
  Widget build(BuildContext context) {
    final chips = [
      for (final destination in destinations)
        Expanded(
          child: Semantics(
            button: true,
            selected: selected == destination,
            label:
                '${_cartDestinationLabel(session, destination)} offers, '
                '${_productCountLabel(session.cartLines.where((line) => line.product.destination == destination).length)}, '
                '${(destination == BuyV2Destination.wholesale ? _packCountLabel : _itemCountLabel)(session.cartLines.where((line) => line.product.destination == destination).fold<int>(0, (sum, line) => sum + line.quantity))}, '
                '${session.procurementPricesUnavailableFor(destination) ? 'Price pending' : _comparisonMoney(session.totalMinorForDestination(destination))}',
            child: Material(
              color: Colors.transparent,
              borderRadius: BorderRadius.circular(12),
              child: InkWell(
                key: ValueKey(
                  'buy-cart-benefit-destination-${destination.name}',
                ),
                onTap: () => onChanged(destination),
                borderRadius: BorderRadius.circular(12),
                child: AnimatedContainer(
                  duration: BuyV2Motion.resolved(
                    context,
                    BuyV2Motion.selection,
                  ),
                  curve: Curves.easeOutCubic,
                  margin: const EdgeInsets.symmetric(vertical: 4),
                  padding: const EdgeInsets.symmetric(horizontal: 7),
                  alignment: Alignment.center,
                  decoration: BoxDecoration(
                    color: selected == destination
                        ? BuyV2ActionStyle.pressedFill
                        : BuyV2ActionStyle.primaryFill,
                    borderRadius: BorderRadius.circular(10),
                    border: Border.all(
                      color: selected == destination
                          ? BuyV2ActionStyle.primaryForeground.withValues(
                              alpha: .32,
                            )
                          : BuyV2Colors.line,
                    ),
                  ),
                  child: FittedBox(
                    fit: BoxFit.scaleDown,
                    child: Text(
                      '${_cartDestinationLabel(session, destination)} · '
                      '${session.procurementPricesUnavailableFor(destination) ? 'Price pending' : _comparisonMoney(session.totalMinorForDestination(destination))}',
                      maxLines: 1,
                      style: TextStyle(
                        color: selected == destination
                            ? BuyV2ActionStyle.primaryForeground
                            : BuyV2Colors.muted,
                        fontSize: 9,
                        fontWeight: selected == destination
                            ? FontWeight.w900
                            : FontWeight.w800,
                      ),
                    ),
                  ),
                ),
              ),
            ),
          ),
        ),
    ];
    final row = Row(
      children: [
        for (var index = 0; index < chips.length; index++) ...[
          if (index > 0) const SizedBox(width: 4),
          chips[index],
        ],
      ],
    );
    return SizedBox(
      key: const ValueKey('buy-cart-benefit-destination-selector'),
      height: BuyV2Metrics.minimumTap,
      child: destinations.length == 1
          ? Align(
              alignment: Alignment.centerLeft,
              child: SizedBox(width: 184, child: row),
            )
          : row,
    );
  }
}

