                    key: ValueKey(
                      'buy-cart-recommendations-${visible.first.destination.name}',
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        for (final shelf in shelves.entries.take(_limit ~/ 6))
                          Padding(
                            key: ValueKey(
                              'buy-cart-category-shelf-${shelf.key}',
                            ),
                            padding: const EdgeInsets.only(bottom: 8),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  children: [
                                    Expanded(
                                      child: Semantics(
                                        header: true,
                                        child: Text(
                                          categoryLabels[shelf.key] ??
                                              'Other products',
                                          style: context.buyBody.copyWith(
                                            fontSize: 12,
                                          ),
                                        ),
                                      ),
                                    ),
                                    if (categoryLabels.containsKey(shelf.key))
                                      TextButton(
                                        key: ValueKey(
                                          'buy-cart-category-view-${shelf.key}',
                                        ),
                                        style: TextButton.styleFrom(
                                          foregroundColor: BuyV2ActionStyle
                                              .primaryForeground,
                                          minimumSize: const Size(44, 44),
                                          padding: const EdgeInsets.symmetric(
                                            horizontal: 6,
                                          ),
                                          textStyle: const TextStyle(
                                            fontFamily: 'Inter',
                                            fontSize: 11,
                                            fontWeight: FontWeight.w600,
                                          ),
                                        ),
                                        onPressed: () =>
                                            _chooseCategory(shelf.key),
                                        child: const Text('See all'),
                                      ),
                                  ],
                                ),
                                _CartProductLane(
                                  session: session,
                                  destination: shelf.value.first.destination,
                                  laneId: 'recommendations-${shelf.key}',
                                  products: shelf.value,
                                  showDeal: true,
                                  reviewScheduledWindow: _purchaseType == 'scheduled',
                                  onBrowseScroll: _browseScroll,
                                ),
                              ],
                            ),
                          ),
                      ],
                    ),
                  ),
          ),
        if (_canBrowseMore)
          Align(
            alignment: Alignment.centerLeft,
            child: TextButton.icon(
              key: const ValueKey('buy-cart-discovery-more'),
              style: TextButton.styleFrom(
                foregroundColor: BuyV2ActionStyle.primaryForeground,
                minimumSize: const Size(44, 44),
                textStyle: const TextStyle(
                  fontFamily: 'Inter',
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                ),
              ),
              onPressed: _loadingMore ? null : _browseMore,
              icon: const Icon(Icons.expand_more, size: 18),
              label: Text(_moreLabel),
            ),
          ),
      ],
    );
  }
}

class _CartProductLane extends StatelessWidget {
  const _CartProductLane({
    required this.session,
    required this.destination,
    required this.laneId,
    required this.products,
    this.showDeal = false,
    this.reviewScheduledWindow = false,
    this.onBrowseScroll,
  });

  final BuyV2Session session;
  final BuyV2Destination destination;
  final String laneId;
  final List<BuyV2Product> products;
  final bool showDeal;
  final bool reviewScheduledWindow;
  final bool Function(ScrollNotification)? onBrowseScroll;

  @override
  Widget build(BuildContext context) {
    return Container(
      key: ValueKey('buy-cart-$laneId-${destination.name}'),
      padding: const EdgeInsets.fromLTRB(0, 0, 0, 4),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          NotificationListener<ScrollNotification>(
            onNotification: onBrowseScroll,
            child: SingleChildScrollView(
              key: PageStorageKey(
                'buy-cart-$laneId-scroll-${destination.name}',
              ),
              scrollDirection: Axis.horizontal,
              physics: const AlwaysScrollableScrollPhysics(),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  for (var index = 0; index < products.length; index++) ...[
                    if (index > 0) const SizedBox(width: 7),
                    _CartRecommendationCard(
                      session: session,
                      product: products[index],
                      showDeal: showDeal,
                      reviewScheduledWindow: reviewScheduledWindow,
                    ),
                  ],
                ],
              ),
            ),
          ),
        ],
      ),
    );
  }
}

class _CartRecommendationCard extends StatelessWidget {
  const _CartRecommendationCard({
    required this.session,
    required this.product,
    this.showDeal = false,
    this.reviewScheduledWindow = false,
  });

  final BuyV2Session session;
  final BuyV2Product product;
  final bool showDeal;
  final bool reviewScheduledWindow;

  @override
  Widget build(BuildContext context) {
    final facts = session.productFactsFor(product);
    final automaticFulfilment = product.destination == BuyV2Destination.shop ||
        product.destination == BuyV2Destination.wholesale;
    final deliveryPromise = automaticFulfilment
        ? buyV2BuyerDeliveryPromise(
            facts,
            confirmAfterStoreAcceptance:
                BuyV2ThemeScope.refinedOf(context) ||
                session.procurementContext?.purpose == BuyV2ProcurementPurpose.restock,
          )
        : facts.deliveryPromise;
    final hasSaving = product.mrpMinor != null && product.mrpMinor! > facts.priceMinor;
    final tier = showDeal ? session.nextCartDealTierFor(product) : null;
    final priceWidth = buyV2ValueTextSize(
      context,
      _comparisonMoney(hasSaving ? product.mrpMinor! : facts.priceMinor),
      const TextStyle(fontSize: 14, fontWeight: FontWeight.w700),
    ).width;
    return SizedBox(
      width: (priceWidth + 60)
          .clamp(
            MediaQuery.textScalerOf(context).scale(1) > 1.6 ? 260.0 : 168.0,
            double.infinity,
          )
          .toDouble(),
      child: Material(
        color: Colors.white,
        elevation: 1,
        shadowColor: BuyV2Colors.ink.withValues(alpha: 0.12),
        borderRadius: BorderRadius.circular(13),
        child: InkWell(
          key: ValueKey('buy-cart-recommendation-${product.id}'),
          onTap: () => session.openProduct(product.id),
          borderRadius: BorderRadius.circular(13),
          child: Padding(
            padding: const EdgeInsets.all(6),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Expanded(
                      child: SizedBox(
                        height: 72,
                        child: BuyV2ProductPackshot(
                          product: product,
                          borderRadius: 10,
                        ),
                      ),
                    ),
                    SizedBox(
                      width: 44,
                      height: 44,
                      child: IconButton(
                        key: ValueKey('buy-save-${product.id}'),
                        tooltip: session.isSaved(product.id)
                            ? 'Remove ${product.customerTitle} from Saved'
                            : 'Save ${product.customerTitle}',
                        onPressed: () {
                          HapticFeedback.selectionClick();
                          session.toggleSaved(product.id);
                        },
                        icon: Icon(
                          session.isSaved(product.id)
                              ? Icons.bookmark_rounded
                              : Icons.bookmark_border_rounded,
                          size: 20,
                          color: BuyV2ActionStyle.primaryForeground,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 5),
                Text(
                  product.customerTitle,
                  style: context.buyBody.copyWith(
                    fontSize: 13,
                    fontWeight: FontWeight.w600,
                    height: 1.2,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  [
                    product.destination == BuyV2Destination.medicine
                        ? product.destination.label
                        : _cartFilterLabel(
                            session.cartPurchaseTypeFor(product),
                          ),
                    product.customerVariantPack,
                    if (facts.priceMinor == product.priceMinor) product.unitPrice,
                  ].where((text) => text.trim().isNotEmpty).join(' · '),
                  style: context.buyMeta.copyWith(fontSize: 11, height: 1.2),
                ),
                if (product.minimumOrder > 1)
                  Text(
                    'Min. qty ${product.minimumOrder}',
                    style: context.buyMeta.copyWith(fontSize: 11, height: 1.2),
                  ),
                Text(
                  product.customerSeller(facts.partner),
                  style: context.buyMeta.copyWith(fontSize: 11, height: 1.2),
                ),
                if (deliveryPromise.trim().isNotEmpty ||
                    facts.deliveryFeeLabel?.trim().isNotEmpty == true)
                  Text(
                    [
                      deliveryPromise,
                      facts.deliveryFeeLabel ?? '',
                    ].where((text) => text.trim().isNotEmpty).join(' · '),
                    style: context.buyMeta.copyWith(fontSize: 11, height: 1.2),
                  ),
                const SizedBox(height: 4),
                if (showDeal && (tier != null || hasSaving))
                  Text(
                    tier != null
                        ? 'Buy ${tier.minimumPacks}+ at ${_comparisonMoney(tier.priceMinor)} each'
                        : 'Save ${_comparisonMoney(product.mrpMinor! - facts.priceMinor)} each',
                    key: ValueKey('buy-cart-deal-${product.id}'),
                    style: context.buyMeta.copyWith(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: BuyV2ActionStyle.primaryForeground,
                    ),
                  ),
                Row(
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            _comparisonMoney(facts.priceMinor),
                            style: const TextStyle(
                              color: BuyV2Colors.ink,
                              fontSize: 14,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                          if (hasSaving)
                            Text(
                              _comparisonMoney(product.mrpMinor!),
                              style: context.buyMeta.copyWith(
                                fontSize: 11,
                                decoration: TextDecoration.lineThrough,
                              ),
                            ),
                        ],
                      ),
                    ),
                    SizedBox(
                      width: 44,
                      height: 44,
                      child: IconButton(
                        key: ValueKey('buy-cart-add-${product.id}'),
                        tooltip: 'Add ${product.customerTitle}',
                        onPressed: () {
                          if (reviewScheduledWindow) {
                            session.openProduct(product.id, reviewScheduledWindow: true);
                            return;
                          }
                          final added = session.addProduct(product.id);
                          if (!added &&
                              session.pendingPrescriptionProductId ==
                                  product.id) {
                            showBuyV2PrescriptionSheet(context, session);
                          }
                        },
                        padding: EdgeInsets.zero,
                        icon: const BuyV2AddFace(),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _CartDeliveryInstructionSections extends StatefulWidget {
  const _CartDeliveryInstructionSections({
    required this.session,
    required this.destinations,
    this.showHeading = true,
    this.publicEditorKey,
  });
  final BuyV2Session session;
  final List<BuyV2Destination> destinations;
  final bool showHeading;
  final GlobalKey<_CartDeliveryInstructionCardState>? publicEditorKey;
  @override
  State<_CartDeliveryInstructionSections> createState() =>
      _CartDeliveryInstructionSectionsState();
}

class _CartDeliveryInstructionSectionsState
    extends State<_CartDeliveryInstructionSections> {
  BuyV2Destination? _selected;
  late String _filter;
  @override
  void initState() {
    super.initState();
    _filter = widget.session.cartDisplayFilter;
    _followFilter();
  }

  void _followFilter() {
    _selected = switch (_filter) {
      'shop' => BuyV2Destination.shop,
      'wholesale' || 'bulk' => BuyV2Destination.wholesale,
      _ => _selected,
    };
  }

  @override
  void didUpdateWidget(covariant _CartDeliveryInstructionSections oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (_filter != widget.session.cartDisplayFilter) {
      _filter = widget.session.cartDisplayFilter;
      _followFilter();
    }
  }

  @override
  Widget build(BuildContext context) {
    final session = widget.session;
    final destinations = session.isStoreProcurement
        ? widget.destinations
        : widget.destinations.take(1);
    final eligible = destinations
        .where(
          (destination) =>
              session.deliveryInstructionsFor(destination).isNotEmpty,
        )
        .toList(growable: false);
    if (eligible.isEmpty) return const SizedBox.shrink();
    final selected = eligible.contains(_selected) ? _selected! : eligible.first;
    return Container(
      key: const ValueKey('buy-cart-instruction-panel'),
      padding: const EdgeInsets.fromLTRB(9, 5, 9, 1),
      decoration: buyV2CardDecoration(context: context, radius: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (widget.showHeading)
            Text(
              'Delivery instructions · optional',
              style: context.buyBody.copyWith(
                fontSize: 12,
                fontWeight: FontWeight.w600,
                color: BuyV2ActionStyle.primaryForeground,
              ),
            ),
          if (session.isStoreProcurement && eligible.length > 1)
            SingleChildScrollView(
              key: const PageStorageKey('buy-cart-instruction-contexts'),
              scrollDirection: Axis.horizontal,
              child: Row(
                children: [
                  for (final destination in eligible)
                    Padding(
                      padding: const EdgeInsets.only(right: 6),
                      child: ChoiceChip(
                        key: ValueKey(
                          'buy-instruction-context-${destination.name}',
                        ),
                        label: Text(
                          _cartDestinationLabel(session, destination),
                        ),
                        selected: selected == destination,
                        showCheckmark: false,
                        side: BorderSide.none,
                        backgroundColor: BuyV2ActionStyle.primaryFill,
                        selectedColor: BuyV2ActionStyle.pressedFill,
                        elevation: selected == destination ? 2 : 0,
                        labelStyle: TextStyle(
                          fontSize: 11,
                          fontWeight: selected == destination
                              ? FontWeight.w700
                              : FontWeight.w500,
                          color: BuyV2ActionStyle.primaryForeground,
                        ),
                        onSelected: (_) {
                          FocusScope.of(context).unfocus();
                          HapticFeedback.selectionClick();
                          setState(() => _selected = destination);
                        },
                      ),
                    ),
                ],
              ),
            ),
          for (final destination in eligible)
            Offstage(
              offstage: destination != selected,
              child: TickerMode(
                enabled: destination == selected,
                child: _CartDeliveryInstructionCard(
                  key:
                      (!session.isStoreProcurement
                          ? widget.publicEditorKey
                          : null) ??
                      ValueKey(
                        'buy-delivery-note-owner-${session.isStoreProcurement ? destination.name : 'delivery'}',
                      ),
                  session: session,
                  destination: destination,
                  showDestination: false,
                ),
              ),
            ),
        ],
      ),
    );
  }
}

class _CartDeliveryInstructionCard extends StatefulWidget {
  const _CartDeliveryInstructionCard({
    super.key,
    required this.session,
    required this.destination,
    required this.showDestination, this.reviewInitialText, this.reviewEffect,
  });

  final BuyV2Session session;
  final BuyV2Destination destination;
  final bool showDestination;
  final String? reviewInitialText;
  final _BuyNativeReviewEffect? reviewEffect;

  @override
  State<_CartDeliveryInstructionCard> createState() =>
      _CartDeliveryInstructionCardState();
}

class _CartDeliveryInstructionCardState
    extends State<_CartDeliveryInstructionCard>
    with WidgetsBindingObserver, AutomaticKeepAliveClientMixin {
  final _noteController = TextEditingController();
  final _noteFocus = FocusNode();
  final _composerKey = GlobalKey();
  final _choiceScrollController = ScrollController();
  bool _revealPending = false;
  bool _editing = false;
  @override
  bool get wantKeepAlive => _editing;
  late BuyV2Session _instructionRegistryOwner;
  bool _commit(bool Function() effect) => !mounted || _BuyShop04Scope.of(context) != null
      ? false : widget.reviewEffect?.call(effect) ?? effect();
  BuyV2Session get session => widget.session;
  BuyV2Destination get destination => widget.destination;
  bool get showDestination => widget.showDestination;
  String get instructionScope =>
      session.isStoreProcurement ? destination.name : 'delivery';
  String get instructionOwner => session.isStoreProcurement
      ? _deliveryInstructionOwner(destination)
      : 'Delivery instructions';

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _noteFocus.addListener(_revealEditor);
    _instructionRegistryOwner = session;
    (_buyInstructionEditors[_instructionRegistryOwner] ??= <_CartDeliveryInstructionCardState>{}).add(this);
    if (widget.reviewInitialText case final text?) {
      _noteController.text = text;
      _editing = true;
    }
  }

  @override
  void didUpdateWidget(covariant _CartDeliveryInstructionCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!identical(_instructionRegistryOwner, widget.session)) {
      _buyInstructionEditors[_instructionRegistryOwner]?.remove(this);
      _instructionRegistryOwner = widget.session;
      (_buyInstructionEditors[_instructionRegistryOwner] ??= <_CartDeliveryInstructionCardState>{}).add(this);
    }
    // Retain this original controller's dirty text across a session replacement.
  }

  @override
  void didChangeMetrics() => _revealEditor();

  void _revealEditor() {
    if (!_editing || !_noteFocus.hasFocus || _revealPending) return;
    _revealPending = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _revealPending = false;
      if (!mounted || !_editing || !_noteFocus.hasFocus) return;
      final editorContext = _composerKey.currentContext;
      if (editorContext == null) return;
      // Keyboard insets settle after focus. Reveal the attached actions too,
      // rather than only the caret, in the resized Cart viewport.
      Scrollable.ensureVisible(
        editorContext,
        alignment: 1,
        alignmentPolicy: ScrollPositionAlignmentPolicy.keepVisibleAtEnd,
      );
    });
  }

  void _closeEditor() {
    setState(() => _editing = false);
    updateKeepAlive();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) {
        Scrollable.ensureVisible(
          context,
          alignmentPolicy: ScrollPositionAlignmentPolicy.keepVisibleAtStart,
        );
      }
    });
  }

  void openEditor({bool focus = false}) {
    if (_BuyShop04Scope.of(context) != null) return;
    if (session.checkoutBusy || session.checkoutRequiresResolution) return;
    if (!_editing) {
      setState(() {
        _noteController.text = session.isStoreProcurement
            ? session.customDeliveryInstructionFor(destination) ?? ''
            : session.publicDeliveryInstruction ??
                  session.previousPublicDeliveryInstructions.join('\n');
        _editing = true;
      });
      updateKeepAlive();
    }
    if (focus) {
      _noteFocus.requestFocus();
      _revealEditor();
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _noteFocus.removeListener(_revealEditor);
    _noteFocus.dispose();
    _buyInstructionEditors[_instructionRegistryOwner]?.remove(this);
    _noteController.dispose();
    _choiceScrollController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final noteActionStyle = TextButton.styleFrom(
      // The shared editor remains alive when filtering moves its list row.
      foregroundColor: BuyV2ActionStyle.primaryForeground,
      minimumSize: const Size(48, 48),
      padding: const EdgeInsets.symmetric(horizontal: 8),
      textStyle: TextStyle(
        fontFamily: BuyV2ThemeScope.refinedOf(context)
            ? Theme.of(context).textTheme.labelLarge?.fontFamily
            : null,
        fontSize: 11,
        fontWeight: FontWeight.w600,
      ),
    );
    super.build(context);
    final locked = session.cartChangesBlocked || _BuyShop04Scope.of(context) != null;
    final options = session.deliveryInstructionsFor(destination);
    final selected = session.selectedDeliveryInstructionFor(destination);
    final customNote = session.customDeliveryInstructionFor(destination);
    return Column(
      key: ValueKey('buy-cart-delivery-instructions-$instructionScope'),
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (showDestination)
          Padding(
            padding: const EdgeInsets.only(top: 3),
            child: Text(
              instructionOwner,
              style: context.buyMeta.copyWith(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: BuyV2ActionStyle.primaryForeground,
              ),
            ),
          ),
        if (session.publicDeliveryInstructionReviewRequired) ...[
          Text(
            'Your previous instructions differ. Review and save one instruction for this address.',
            style: context.buyBody,
          ),
          for (final note in session.previousPublicDeliveryInstructions)
            Text(note, style: context.buyMeta),
        ],
        Row(
          key: ValueKey('buy-instruction-scroll-cue-$instructionScope'),
          children: [
            Expanded(
              child: SingleChildScrollView(
                key: PageStorageKey('buy-instruction-lane-$instructionScope'),
                controller: _choiceScrollController,
                scrollDirection: Axis.horizontal,
                child: Row(
                  children: [
                    if (session.isStoreProcurement && selected != null)
                      TextButton(
                        key: ValueKey(
                          'buy-cart-instruction-$instructionScope-none',
                        ),
                        style: TextButton.styleFrom(
                          foregroundColor: BuyV2ActionStyle.primaryForeground,
                          minimumSize: const Size(48, 48),
                          textStyle: const TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                          ),
                          padding: const EdgeInsets.only(right: 14),
                        ),
                        onPressed: () {
                          HapticFeedback.selectionClick();
                          _commit(() => session.chooseDeliveryInstruction(
                            destination: destination,
                            instructionId: null,
                          ));
                        },
                        child: const Text('Clear'),
                      ),
                    TextButton.icon(
                      style: noteActionStyle,
                      key: ValueKey(
                        'buy-cart-instruction-custom-$instructionScope',
                      ),
                      onPressed: locked ? null : openEditor,
                      icon: const Icon(Icons.edit_outlined, size: 16),
                      label: const Text('Add instructions'),
                    ),
                    for (var index = 0; index < options.length; index++)
                      Builder(
                        builder: (context) {
                          final option = options[index];
                          final isSelected = selected?.id == option.id;
                          final label = option.label;
                          return Semantics(
                            checked: isSelected,
                            enabled: locked ? false : null,
                            inMutuallyExclusiveGroup: true,
                            label: '$instructionOwner: $label',
                            child: Material(
                              color: Colors.transparent,
                              child: InkWell(
                                key: ValueKey(
                                  'buy-cart-instruction-$instructionScope-${option.id}',
                                ),
                                borderRadius: BorderRadius.circular(8),
                                onTap: locked
                                    ? null
                                    : () {
                                        HapticFeedback.selectionClick();
                                        _commit(() => session.chooseDeliveryInstruction(
                                          destination: destination,
                                          instructionId: option.id,
                                        ));
                                      },
                                child: ConstrainedBox(
                                  constraints: const BoxConstraints(
                                    minHeight: 48,
                                  ),
                                  child: Padding(
                                    padding: const EdgeInsets.only(right: 14),
                                    child: Row(
                                      mainAxisSize: MainAxisSize.min,
                                      children: [
                                        Icon(
                                          isSelected
                                              ? Icons.radio_button_checked
                                              : Icons.radio_button_unchecked,
                                          size: 18,
                                          color: BuyV2ActionStyle
                                              .primaryForeground,
                                        ),
                                        const SizedBox(width: 5),
                                        ExcludeSemantics(
                                          child: Text(
                                            label,
                                            softWrap: false,
                                            style: context.buyBody.copyWith(
                                              fontSize: 11,
                                              fontWeight: isSelected
                                                  ? FontWeight.w600
                                                  : FontWeight.w400,
                                              color: BuyV2ActionStyle
                                                  .primaryForeground,
                                            ),
                                          ),
                                        ),
                                      ],
                                    ),
                                  ),
                                ),
                              ),
                            ),
                          );
                        },
                      ),
                  ],
                ),
              ),
            ),
            AnimatedBuilder(
              animation: _choiceScrollController,
              builder: (context, _) {
                final position = _choiceScrollController.hasClients
                    ? _choiceScrollController.position
                    : null;
                final atEnd =
                    position != null &&
                    position.hasContentDimensions &&
                    position.pixels >= position.maxScrollExtent - 1;
                return IconButton(
                  key: ValueKey(
                    'buy-instruction-scroll-action-$instructionScope',
                  ),
                  tooltip: atEnd
                      ? 'Back to first instructions'
                      : 'More instructions',
                  constraints: const BoxConstraints(
                    minWidth: 44,
                    minHeight: 48,
                  ),
                  visualDensity: VisualDensity.standard,
                  icon: Icon(
                    atEnd
                        ? Icons.chevron_left_rounded
                        : Icons.chevron_right_rounded,
                  ),
                  onPressed: () {
                    if (!_choiceScrollController.hasClients) return;
                    final position = _choiceScrollController.position;
                    final target = atEnd
                        ? position.minScrollExtent
                        : (position.pixels + position.viewportDimension)
                              .clamp(
                                position.minScrollExtent,
                                position.maxScrollExtent,
                              )
                              .toDouble();
                    if (MediaQuery.disableAnimationsOf(context)) {
                      _choiceScrollController.jumpTo(target);
                    } else {
                      _choiceScrollController.animateTo(
                        target,
                        duration: const Duration(milliseconds: 200),
                        curve: Curves.easeOut,
                      );
                    }
                  },
                );
              },
            ),
          ],
        ),
        if (_editing)
          KeyedSubtree(
            key: _composerKey,
            child: Container(
              key: ValueKey('buy-cart-instruction-composer-$instructionScope'),
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: const Color(0xFFDADDE5)),
              ),
              padding: const EdgeInsets.symmetric(horizontal: 4),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  TextField(
                    key: ValueKey(
                      'buy-cart-instruction-note-$instructionScope',
                    ),
                    controller: _noteController,
                    enabled: !locked,
                    focusNode: _noteFocus,
                    onChanged: (_) => _revealEditor(),
                    autofocus: true,
                    minLines: 1,
                    maxLines: 3,
                    maxLength: 200,
                    textCapitalization: TextCapitalization.sentences,
                    decoration: const InputDecoration(
                      labelText: 'Delivery instructions (optional)',
                      hintText: 'For example, use the side entrance',
                      isDense: true,
                      filled: false,
                      contentPadding: EdgeInsets.fromLTRB(8, 12, 8, 4),
                      border: InputBorder.none,
                      enabledBorder: InputBorder.none,
                      focusedBorder: InputBorder.none,
                      counterText: '',
                      labelStyle: TextStyle(
                        color: BuyV2ActionStyle.primaryForeground,
                      ),
                    ),
                  ),
                  Wrap(
                    spacing: 4,
                    children: [
                      TextButton(
                        style: noteActionStyle,
                        key: ValueKey(
                          'buy-cart-instruction-clear-draft-$instructionScope',
                        ),
                        onPressed: _noteController.clear,
                        child: const Text('Clear'),
                      ),
                      TextButton(
                        style: noteActionStyle,
                        key: ValueKey(
                          'buy-cart-instruction-save-$instructionScope',
                        ),
                        onPressed: locked
                            ? null
                            : () {
                                if (_commit(() => session.setCustomDeliveryInstruction(
                                  destination: destination,
                                  text: _noteController.text,
                                ))) {
                                  if (!mounted) return;
                                  FocusScope.of(context).unfocus();
                                  _closeEditor();
                                }
                              },
                        child: const Text('Save'),
                      ),
                      TextButton(
                        style: noteActionStyle,
                        onPressed: () {
                          FocusScope.of(context).unfocus();
                          _closeEditor();
                        },
                        child: const Text('Cancel'),
                      ),
                    ],
                  ),
                ],
              ),
            ),
          )
        else if (customNote != null)
          Text(
            customNote,
            key: ValueKey('buy-cart-instruction-saved-$instructionScope'),
            style: context.buyBody,
          ),
      ],
    );
  }
}

class _CartTipSections extends StatelessWidget {
  const _CartTipSections({required this.session});

  final BuyV2Session session;

  @override
  Widget build(BuildContext context) {
    final eligible = session.scopedCartFulfilmentGroups
        .where((group) => session.tipOptionsFor(group.destination).isNotEmpty)
        .toList(growable: false);
    if (eligible.isEmpty) return const SizedBox.shrink();
    return Column(
      children: [
        for (final group in eligible) ...[
          _CartTipCard(session: session, group: group),
          const SizedBox(height: 10),
        ],
      ],
    );
  }
}

class _CartTipCard extends StatelessWidget {
  const _CartTipCard({required this.session, required this.group, this.reviewAmount, this.reviewEffect});

  final BuyV2Session session;
  final BuyV2FulfilmentGroup group;
  final int? reviewAmount;
  final _BuyNativeReviewEffect? reviewEffect;
  bool _choose(int amount) {
    bool effect() => session.chooseTip(fulfilmentKey: group.key, destination: group.destination, amount: amount);
    return reviewEffect?.call(effect) ?? effect();
  }

  @override
  Widget build(BuildContext context) {
    final selected = reviewAmount ?? session.tipForGroup(group);
    final options = session.tipOptionsFor(group.destination);
    final title = group.destination == BuyV2Destination.medicine
        ? 'Tip pharmacy delivery partner'
        : 'Tip Shop delivery partner';
    return Container(
      key: ValueKey('buy-cart-tip-${group.key}'),
      padding: const EdgeInsets.all(9),
      decoration: buyV2CardDecoration(
        context: context,
        color: BuyV2Colors.softGreen,
        border: const Color(0x33138808),
        radius: 15,
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(title, style: context.buyTitle.copyWith(fontSize: 14)),
          const SizedBox(height: 2),
          Text(
            '${group.customerPartner} · optional for this delivery only',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: context.buyMeta.copyWith(fontSize: 8),
          ),
          const SizedBox(height: 7),
          Wrap(
            spacing: 6,
            runSpacing: 6,
            children: [
              ChoiceChip(
                side: const BorderSide(color: BuyV2ActionStyle.primaryBorder),
                checkmarkColor: BuyV2ActionStyle.primaryForeground,
                backgroundColor: BuyV2ActionStyle.primaryFill,
                selectedColor: BuyV2ActionStyle.pressedFill,
                labelStyle: (TextStyle(
                  color: BuyV2ActionStyle.foreground,
                )).copyWith(color: BuyV2ActionStyle.primaryForeground),
                key: ValueKey('buy-cart-tip-${group.key}-0'),
                label: const Text('No tip'),
                selected: selected == 0,
                onSelected: session.cartChangesBlocked
                    ? null
                    : (_) => _choose(0),
              ),
              for (final option in options)
                ChoiceChip(
                  side: const BorderSide(color: BuyV2ActionStyle.primaryBorder),
                  checkmarkColor: BuyV2ActionStyle.primaryForeground,
                  backgroundColor: BuyV2ActionStyle.primaryFill,
                  selectedColor: BuyV2ActionStyle.pressedFill,
                  labelStyle: (TextStyle(
                    color: BuyV2ActionStyle.foreground,
                  )).copyWith(color: BuyV2ActionStyle.primaryForeground),
                  key: ValueKey('buy-cart-tip-${group.key}-${option.amount}'),
                  label: Text(buyV2Money(option.amount)),
                  selected: selected == option.amount,
                  onSelected: session.cartChangesBlocked
                      ? null
                      : (_) => _choose(option.amount),
                ),
            ],
          ),
        ],
      ),
    );
  }
}

class _CartBillSummary extends StatelessWidget {
  const _CartBillSummary({required this.session});

  final BuyV2Session session;

  @override
  Widget build(BuildContext context) {
    if (session.hasSupplierQuoteProducts) {
      return Padding(key: const ValueKey('buy-cart-bill-summary'), padding: const EdgeInsets.symmetric(vertical: 8),
        child: Text('Supplier prices cover products only. Coupons, tax, delivery charges and payment terms are confirmed at Checkout.', style: context.buyMeta));
    }
    if (session.scopedProcurementPricesUnavailable) {
      return Container(
        key: const ValueKey('buy-cart-bill-summary'),
        padding: const EdgeInsets.all(11),
        decoration: buyV2CardDecoration(context: context, radius: 15),
        child: Text(
          'A retained item has no confirmed price. Review or remove it before ordering.',
          style: context.buyMeta,
        ),
      );
    }
    final familyTotals = session.scopedCartFamilyTotalsMinor;
    return Container(
      key: const ValueKey('buy-cart-bill-summary'),
      padding: const EdgeInsets.all(11),
      decoration: buyV2CardDecoration(context: context, radius: 15),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              const Icon(
                Icons.receipt_long_outlined,
                color: BuyV2Colors.ink,
                size: 20,
              ),
              const SizedBox(width: 7),
              Text(
                'Bill summary',
                style: context.buyTitle.copyWith(
                  fontSize: 14,
                  fontWeight: FontWeight.w600,
                  letterSpacing: 0,
                ),
              ),
            ],
          ),
          const SizedBox(height: 5),
          for (final entry in familyTotals.entries)
            _CartAmountRow(
              label:
                  '${_cartDestinationLabel(session, entry.key)} ${_cartItemFamilyLabel(entry.key).toLowerCase()}',
              value: _comparisonMoney(entry.value),
            ),
          if (session.scopedCartSavingsMinor + session.scopedCouponSavingMinor > 0)
            _CartSavingsSummary(session: session),
          if (session.scopedTipTotal > 0)
            _CartAmountRow(
              label: 'Optional delivery tips',
              value: buyV2Money(session.scopedTipTotal),
            ),
          const Divider(height: 16),
          _CartAmountRow(
            label: 'Cart total',
            value: _comparisonMoney(session.scopedPayableTotalMinor),
            strong: true,
          ),
          const SizedBox(height: 5),
          Text(
            'Delivery charges, if any, are confirmed at checkout.',
            style: context.buyMeta.copyWith(fontSize: 11),
          ),
        ],
      ),
    );
  }
}

class _CartAmountRow extends StatelessWidget {
  const _CartAmountRow({
    required this.label,
    required this.value,
    this.valueColor,
    this.strong = false,
    this.stacked = false,
  });

  final String label;
  final String value;
  final Color? valueColor;
  final bool strong;
  final bool stacked;

  @override
  Widget build(BuildContext context) {
    final labelText = Text(
      label,
      style: strong ? context.buyBody : context.buyMeta,
    );
    final valueText = Text(
      value,
      style: TextStyle(
        color: valueColor ?? BuyV2Colors.ink,
        fontSize: strong ? 14 : 12,
        fontWeight: strong ? FontWeight.w700 : FontWeight.w600,
      ),
    );
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: stacked
          ? Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [labelText, const SizedBox(height: 2), valueText],
            )
          : Row(
              children: [
                Expanded(child: labelText),
                valueText,
              ],
            ),
    );
  }
}

class _CartSavingsSummary extends StatelessWidget {
  const _CartSavingsSummary({required this.session});

  final BuyV2Session session;

  @override
  Widget build(BuildContext context) {
    final productSaving = session.scopedCartSavingsMinor;
    final couponSaving = session.scopedCouponSavingMinor;
    final savings = productSaving + couponSaving;
    return Padding(
      key: const ValueKey('buy-cart-savings-summary'),
      padding: const EdgeInsets.symmetric(vertical: 4),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Icon(
            Icons.savings_outlined,
            color: BuyV2Colors.green,
            size: 18,
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'You save ${_comparisonMoney(savings)}',
                  style: context.buyBody.copyWith(fontSize: 12),
                ),
                Text(
                  [
                    if (productSaving > 0)
                      'Listed MRP saving ${_comparisonMoney(productSaving)}',
                    if (couponSaving > 0)
                      'Applied coupon ${_comparisonMoney(couponSaving)}',
                  ].join(' · '),
                  style: context.buyMeta.copyWith(fontSize: 11),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

class _CartLine extends StatelessWidget {
  const _CartLine({required this.session, required this.line,this.reviewRemove});

  final BuyV2Session session;
  final BuyV2CartLine line;
  final VoidCallback? reviewRemove;

  @override
  Widget build(BuildContext context) {
    final product = line.product;
    final compactSupplier = session.procurementContext?.purpose == BuyV2ProcurementPurpose.restock;
    final agreed = session.agreedUnitPriceFor(line);
    final publishedBulk = session.usesRetainedSupplierAgreement(product);
    final priceUnavailable = publishedBulk && agreed == null || product.packTerms?.commodityPriceRevision != null &&
      product.packTerms?.pricingCurrentAt(session.catalogueNow()) != true || session.procurementRetainedPriceUnavailable(
      product,
    );
    final facts = session.productFactsFor(product);
    final wholesale = product.destination == BuyV2Destination.wholesale;
    final quantityTier = priceUnavailable
        ? null
        : session.nextCartDealTierFor(product);
    final automaticFulfilment =
        product.destination == BuyV2Destination.shop ||
        product.destination == BuyV2Destination.wholesale;
    final compactTitle =
        automaticFulfilment &&
        !session.isStoreProcurement &&
        BuyV2ThemeScope.refinedOf(context);
    final titleStyle = context.buyBody.copyWith(
      fontSize: compactTitle ? 13 : 14,
      fontWeight: compactTitle ? FontWeight.w600 : null,
    );
    final buyerPromise = automaticFulfilment
        ? buyV2BuyerDeliveryPromise(
            facts,
            confirmAfterStoreAcceptance:
                product.destination != BuyV2Destination.medicine &&
                BuyV2ThemeScope.refinedOf(context),
          )
        : product.deliveryPromise;
    // Keep the complete illustration disclosure readable in a Cart thumbnail.
    // Its measured width grows with accessibility text instead of hiding media.
    final thumbnailExtent =
        (buyV2ValueTextSize(
                  context,
                  BuyV2ProductPackshot.illustrationLabel(product),
                  const TextStyle(
                    fontSize: 10,
                    height: 1.2,
                    fontWeight: FontWeight.w600,
                  ),
                ).width.ceilToDouble() +
                10)
            .clamp(76.0, double.infinity)
            .toDouble();
    final stockLabel = session.storeStockLabelFor(product);
    final gstDisclosure = product.packTerms == null ? null :
      '${_supplierGstDisclosure(product.packTerms, facts.stale ? null : session.supplierTaxForLine(line))}. Final tax confirmed at checkout.';
    final productDetailsLabel = 'View ${product.customerTitle} product details${stockLabel == null ? '' : '. $stockLabel'}'
      '${gstDisclosure == null ? '' : '. $gstDisclosure'}'
      '${compactSupplier ? '. Supplier: ${product.customerSeller(automaticFulfilment ? facts.partner : product.seller)}' : ''}';
    void openProductDetails() {
      if(reviewRemove!=null)return;
      HapticFeedback.selectionClick();
      session.openProduct(product.id);
    }

    final VoidCallback? detailsAction=reviewRemove==null?openProductDetails:null;
    final photo = SizedBox(
      key: ValueKey('buy-cart-packshot-${product.id}'),
      width: thumbnailExtent,
      height: thumbnailExtent,
      child: GestureDetector(
        excludeFromSemantics: true,
        onTap: detailsAction,
        child: BuyV2ProductPackshot(product: product, borderRadius: 11),
      ),
    );
    final productDetails = BuyV2IntentDepth(
      key: ValueKey('buy-cart-product-depth-${product.id}'),
      enabled: false,
      child: Semantics(
        key: ValueKey('buy-cart-product-summary-${product.id}'),
        container: true,
        button: reviewRemove==null,
        label: productDetailsLabel,
        excludeSemantics: true,
        onTap: detailsAction,
        child: Material(
          color: Colors.transparent,
          borderRadius: BorderRadius.circular(11),
          child: InkWell(
            key: ValueKey('buy-cart-product-details-${product.id}'),
            onTap: detailsAction,
            highlightColor: Colors.transparent,
            splashColor: Colors.transparent,
            borderRadius: BorderRadius.circular(11),
            child: ConstrainedBox(
              constraints: const BoxConstraints(minHeight: 44),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          product.customerTitle,
                          style: titleStyle,
                          maxLines: compactTitle
                              ? MediaQuery.textScalerOf(context).scale(1) > 1.2
                                    ? 3
                                    : 2
                              : null,
                          overflow: compactTitle ? TextOverflow.ellipsis : null,
                        ),
                        Text(
                          product.packTerms != null ||
                                  product.hasStructuredVariants
                              ? product.customerVariantPack
                              : '${product.customerVariant} · ${product.pack}',
                          style: context.buyMeta.copyWith(fontSize: 11),
                        ),
                        Text(
                          product.customerSeller(
                            automaticFulfilment
                                ? facts.partner
                                : product.seller,
                          ),
                          key: ValueKey('buy-cart-supplier-name-${product.id}'),
                          maxLines: compactSupplier ? 1 : null,
                          overflow: compactSupplier ? TextOverflow.ellipsis : null,
                          style: context.buyMeta.copyWith(fontSize: compactSupplier ? 10 : 11),
                        ),
                        Text(
                          buyerPromise,
                          style: context.buyMeta.copyWith(fontSize: 11),
                        ),
                        if (stockLabel != null) Text(stockLabel,
                          key: ValueKey('buy-cart-stock-${product.id}'),
                          style: context.buyMeta.copyWith(fontSize: 11)),
                        if (gstDisclosure != null) Text(
                          gstDisclosure,
                          key: ValueKey('buy-cart-supplier-gst-${product.id}'),
                          style: context.buyMeta.copyWith(fontSize: 11)),
                      ],
                    ),
                  ),
                  const Icon(
                    Icons.chevron_right_rounded,
                    size: 18,
                    color: BuyV2Colors.ink,
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );

    final tradeFacts = wholesale
        ? Semantics(
            key: ValueKey('buy-wholesale-cart-line-facts-${product.id}'),
            container: true,
            label:
                'Minimum order ${_packCountLabel(product.minimumOrder)}. '
                '${_comparisonMoney(agreed ?? product.priceMinor)} per pack. ${agreed == null ? product.unitPrice : 'Agreed supplier price'}. '
                '${product.freightIncluded ? 'Freight included in price.' : 'Freight confirmed before payment.'}',
            excludeSemantics: true,
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 5),
              decoration: BoxDecoration(
                color: BuyV2Colors.canvas,
                borderRadius: BorderRadius.circular(9),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    priceUnavailable
                        ? 'Price unavailable'
                        : 'Minimum order ${_packCountLabel(product.minimumOrder)} · '
                              '${_comparisonMoney(agreed ?? product.priceMinor)} per pack',
                    style: context.buyMeta.copyWith(
                      color: BuyV2Colors.ink,
                      fontSize: 11,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                  const SizedBox(height: 2),
                  Text(
                    '${agreed == null ? product.unitPrice : 'Agreed supplier price'} · '
                    '${product.freightIncluded ? 'Freight included' : 'Freight confirmed later'}',
                    style: context.buyMeta.copyWith(fontSize: 11),
                  ),
                ],
              ),
            ),
          )
        : null;

    const lineTotalStyle = TextStyle(
      color: BuyV2Colors.ink,
      fontSize: 16,
      fontWeight: FontWeight.w700,
    );
    final lineTotalText = priceUnavailable
        ? 'Price pending'
        : _comparisonMoney(session.merchandiseForLine(line));
    final lineTotalSize = buyV2ValueTextSize(
      context,
      lineTotalText,
      lineTotalStyle,
    );
    const quantityStyle = TextStyle(
      inherit: false,
      fontFamily: 'Inter',
      color: BuyV2Colors.ink,
      fontSize: 13,
      fontWeight: FontWeight.w700,
    );
    final quantitySize = buyV2ValueTextSize(
      context,
      '${line.quantity}',
      quantityStyle,
    );
    final price = Column(
      crossAxisAlignment: CrossAxisAlignment.end,
      mainAxisSize: MainAxisSize.min,
      children: [
        if (wholesale)
          Text(
            priceUnavailable ? 'Retained item' : 'Item total',
            style: context.buyMeta.copyWith(fontSize: 11),
          ),
        BuyV2FiniteValueTransition(
          key: ValueKey('buy-cart-line-total-motion-${product.id}'),
          incomingOnly: true,
          stateKey: session.merchandiseForLine(line),
          text: lineTotalText,
          ownerSize: lineTotalSize,
          textAlign: TextAlign.end,
          style: lineTotalStyle,
        ),
        if (!wholesale &&
            !priceUnavailable &&
            product.packTerms?.priceTiers.isNotEmpty != true &&
            product.unitPrice.trim().isNotEmpty)
          Text(
            product.unitPrice,
            style: context.buyMeta.copyWith(fontSize: 11),
          ),
        if (product.mrpMinor != null && product.mrpMinor! > product.priceMinor)
          Text(
            _comparisonMoney(buyV2MultiplyMinor(product.mrpMinor!, line.quantity)),
            style: context.buyMeta.copyWith(
              fontSize: 11,
              decoration: TextDecoration.lineThrough,
            ),
          ),
      ],
    );

    final quantityControl = SizedBox(
      height: (quantitySize.height + 8).clamp(44.0, double.infinity).toDouble(),
      child: Stack(
        children: [
          Positioned.fill(
            top: 6,
            bottom: 6,
            child: DecoratedBox(
              key: ValueKey('buy-cart-quantity-pill-${product.id}'),
              decoration: BoxDecoration(
                color: BuyV2ActionStyle.primaryFill,
                borderRadius: BorderRadius.circular(8),
              ),
            ),
          ),
          Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              IconButton(
                tooltip: reviewRemove!=null ? 'Remove ${product.customerTitle} from Cart' : product.quantityStep > 1
                    ? line.quantity <= product.minimumOrder
                          ? 'Remove ${product.customerTitle} from Cart'
                          : 'Remove ${product.quantityStep} packs'
                    : wholesale
                    ? line.quantity <= product.minimumOrder
                          ? 'Remove ${product.customerTitle} from Cart'
                          : 'Remove one trade pack'
                    : 'Remove one',
                onPressed: session.cartChangesBlocked ? null : reviewRemove ?? () => session.decrease(product.id),
                visualDensity: compactTitle
                    ? VisualDensity.standard
                    : VisualDensity.compact,
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 44, minHeight: 44),
                icon: const Icon(Icons.remove, size: 15),
              ),
              SizedBox(
                key: ValueKey('buy-cart-quantity-${product.id}'),
                width: quantitySize.width
                    .clamp(48.0, double.infinity)
                    .toDouble(),
                height: 48,
                child: Center(
                  child: Semantics(
                    label:
                        '${product.customerTitle}, ${_packCountLabel(line.quantity)} in Cart',
                    excludeSemantics: true,
                    child: BuyV2FiniteValueTransition(
                      key: ValueKey(
                        'buy-cart-line-quantity-motion-${product.id}',
                      ),
                      incomingOnly: true,
                      stateKey: line.quantity,
                      text: '${line.quantity}',
                      ownerSize: Size(
                        quantitySize.width
                            .clamp(44.0, double.infinity)
                            .toDouble(),
                        quantitySize.height
                            .clamp(28.0, double.infinity)
                            .toDouble(),
                      ),
                      style: quantityStyle,
                    ),
                  ),
                ),
              ),
              IconButton(
                tooltip: product.quantityStep > 1
                    ? 'Add ${product.quantityStep} packs'
                    : wholesale
                    ? 'Add one trade pack'
                    : 'Add one',
                onPressed: session.cartChangesBlocked || reviewRemove!=null ? null : () => session.increase(product.id),
                visualDensity: compactTitle
                    ? VisualDensity.standard
                    : VisualDensity.compact,
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 44, minHeight: 44),
                icon: const Icon(Icons.add, size: 15),
              ),
            ],
          ),
        ],
      ),
    );

    return Container(
      key: ValueKey('buy-cart-line-${product.id}'),
      decoration: buyV2CardDecoration(context: context, radius: 14),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              if (session.usesMixedCartSelection)
                Checkbox(
                  key: ValueKey('buy-cart-select-${product.id}'),
                  value: session.cartProductSelected(product.id),
                  activeColor: BuyV2ActionStyle.primaryForeground,
                  semanticLabel: 'Include ${product.customerTitle} in checkout',
                  onChanged: session.cartChangesBlocked || reviewRemove!=null
                      ? null
                      : (value) => session.selectCartProduct(
                          product.id,
                          value == true,
                        ),
                ),
              if(reviewRemove==null)Expanded(
                child: BuyV2ProductEdgeControls(
                  session: session,
                  product: product,
                ),
              ),
            ],
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(10, 0, 9, 7),
            child: LayoutBuilder(
              builder: (context, constraints) {
                final metadataWidth =
                    constraints.maxWidth - thumbnailExtent - 8;
                final stackMedia =
                    MediaQuery.textScalerOf(context).scale(1) > 1.2 ||
                    metadataWidth < 160 ||
                    [
                      product.customerTitle,
                      product.customerVariantPack,
                      product.customerSeller(
                        automaticFulfilment ? facts.partner : product.seller,
                      ),
                    ].any(
                      (text) => text
                          .split(RegExp(r'\s+'))
                          .any(
                            (word) =>
                                buyV2ValueTextSize(
                                  context,
                                  word,
                                  context.buyBody.copyWith(fontSize: 14),
                                ).width >
                                metadataWidth - 18,
                          ),
                    );
                final purchaseControls = Wrap(
                  alignment: WrapAlignment.spaceBetween,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  spacing: 8,
                  runSpacing: 4,
                  children: [price, quantityControl],
                );
                return Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    if (stackMedia) ...[
                      photo,
                      const SizedBox(height: 4),
                      productDetails,
                      purchaseControls,
                    ] else
                      Row(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          photo,
                          const SizedBox(width: 8),
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.stretch,
                              children: [
                                productDetails,
                                if (!compactTitle) purchaseControls,
                              ],
                            ),
                          ),
                        ],
                      ),
                    if (compactTitle && !stackMedia) purchaseControls,
                    if(reviewRemove==null)BuyV2AdvertisedOfferLink(session: session, product: product),
                    BuyV2PriceFreshness(product: product, now: session.catalogueNow,
                      onRequestRefresh: reviewRemove!=null?null:() => session.requestCommodityPriceRefresh(product)),
                    if (line.scheduledFulfilment case final selected?) ...[
                      const SizedBox(height: 5),
                      Text('Requested delivery · ${_scheduledWindowLabel(context, selected)}',
                        key: ValueKey('buy-cart-selected-window-${product.id}'),
                        style: context.buyMeta.copyWith(color: BuyV2Colors.navy)),
                      TextButton(
                        style: TextButton.styleFrom(alignment: Alignment.centerLeft, minimumSize: const Size(48, 48)),
                        onPressed: reviewRemove!=null?null:() => session.openProduct(product.id, reviewScheduledWindow: true),
                        child: const Text('Review delivery window')),
                    ],
                    if (tradeFacts != null) ...[
                      const SizedBox(height: 4),
                      tradeFacts,
                    ],
                    if (quantityTier != null)
                      TextButton(
                        key: ValueKey('buy-cart-quantity-tier-${product.id}'),
                        style: TextButton.styleFrom(
                          alignment: Alignment.centerLeft,
                          foregroundColor: BuyV2ActionStyle.primaryForeground,
                          padding: const EdgeInsets.symmetric(vertical: 4),
                          minimumSize: const Size(44, 44),
                        ),
                        onPressed: reviewRemove!=null?null:() => session.setCartQuantity(
                          product.id,
                          '${quantityTier.minimumPacks}',
                        ),
                        child: Text(
                          '${_packCountLabel(quantityTier.minimumPacks - line.quantity)} more'
                          ' → ${_comparisonMoney(quantityTier.priceMinor)}/pack'
                          ' · Item total ${_comparisonMoney(buyV2MultiplyMinor(quantityTier.priceMinor, quantityTier.minimumPacks))}'
                          '${product.packTerms?.pricesIncludeTax == null
                              ? ''
                              : product.packTerms!.pricesIncludeTax!
                              ? ' · Tax included'
                              : ' · Tax extra'}'
                          '${product.packTerms?.pricesIncludeFreight == null
                              ? ''
                              : product.packTerms!.pricesIncludeFreight!
                              ? ' · Delivery included'
                              : ' · Delivery extra'}',
                          style: context.buyBody.copyWith(
                            fontSize: 12,
                            fontWeight: FontWeight.w600,
                            height: 1.3,
                          ),
                        ),
                      ),
                  ],
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

