class _TrackingTimeline extends StatelessWidget {
  const _TrackingTimeline({required this.order});

  final BuyV2Order order;

  @override
  Widget build(BuildContext context) {
    final completedSteps = switch (order.status) {
      BuyV2OrderStatus.preparing => 1,
      BuyV2OrderStatus.confirmed => 0,
      BuyV2OrderStatus.dispatched => 2,
      BuyV2OrderStatus.arriving => 3,
      BuyV2OrderStatus.delivered => 5,
    };
    final publicStageDescriptions =
        order.destination != BuyV2Destination.medicine &&
        BuyV2ThemeScope.refinedOf(context);
    final steps = [
      ('Confirmed', 'Order confirmation recorded'),
      (
        'Packing',
        publicStageDescriptions
            ? 'Item checking and packing'
            : 'Items are being checked and packed',
      ),
      ('Dispatched', 'Partner handed over the order'),
      (
        'Arriving',
        publicStageDescriptions
            ? 'Journey to the delivery address'
            : 'Delivery is travelling to the address',
      ),
      ('Delivered', 'Delivery confirmation at the address'),
    ];
    return Container(
      padding: const EdgeInsets.all(8),
      decoration: buyV2CardDecoration(context: context, radius: 13),
      child: Column(
        children: [
          for (final indexed in steps.indexed)
            Padding(
              padding: EdgeInsets.only(
                bottom: indexed.$1 == steps.length - 1 ? 0 : 5,
              ),
              child: Semantics(
                label:
                    '${indexed.$2.$1}. ${indexed.$2.$2}. '
                    '${indexed.$1 < completedSteps
                        ? 'Complete'
                        : indexed.$1 == completedSteps
                        ? 'Last recorded stage'
                        : 'Upcoming'}',
                excludeSemantics: true,
                child: Row(
                  children: [
                    AnimatedContainer(
                      duration: BuyV2Motion.resolved(
                        context,
                        BuyV2Motion.stateChange,
                      ),
                      curve: Curves.easeInOutCubic,
                      width: 21,
                      height: 21,
                      decoration: BoxDecoration(
                        color: indexed.$1 < completedSteps
                            ? BuyV2Colors.green
                            : indexed.$1 == completedSteps
                            ? BuyV2Colors.softOrange
                            : BuyV2Colors.softBlue,
                        shape: BoxShape.circle,
                      ),
                      child: AnimatedSwitcher(
                        duration: BuyV2Motion.resolved(
                          context,
                          BuyV2Motion.stateChange,
                        ),
                        child: Icon(
                          key: ValueKey(
                            'tracking-step-${indexed.$1}-$completedSteps',
                          ),
                          indexed.$1 < completedSteps
                              ? Icons.check
                              : indexed.$1 == completedSteps
                              ? Icons.radio_button_checked_rounded
                              : Icons.circle_outlined,
                          size: 13,
                          color: indexed.$1 < completedSteps
                              ? Colors.white
                              : indexed.$1 == completedSteps
                              ? BuyV2Colors.orange
                              : BuyV2Colors.muted,
                        ),
                      ),
                    ),
                    const SizedBox(width: 7),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(indexed.$2.$1, style: context.buyBody),
                          Text(indexed.$2.$2, style: context.buyMeta),
                        ],
                      ),
                    ),
                    if (indexed.$1 == completedSteps)
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 6,
                          vertical: 3,
                        ),
                        decoration: BoxDecoration(
                          color: BuyV2Colors.softOrange,
                          borderRadius: BorderRadius.circular(7),
                        ),
                        child: const Text(
                          'RECORDED',
                          style: TextStyle(
                            color: BuyV2Colors.navy,
                            fontSize: 7,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                  ],
                ),
              ),
            ),
        ],
      ),
    );
  }
}

